import React, { Component } from 'react'
import { Table } from 'antd'
import ReactJson from 'react-json-view'
import { get } from 'lodash'
import moment from 'moment-timezone'

import ObjectConverter from '../../../../../helpers/objectConverter'
import { Header } from '../../../../../components/StyledComponents'
import { RemarkStyle, RemarksDiv } from './component.style'
import { APP_COLORS } from '../../../../../constants/colors'


class Remarks extends Component {

  render() {
    const { remarks = [] } = this.props
    const columns = [{
      title: 'Remark',
      key: 'remark',
      dataIndex: 'remark',
      width: '30%',
      render: remark => {
        let dataRemark = ""
        let objConverter = ObjectConverter(remark)
        if (typeof objConverter === 'object' && objConverter !== null) {
          dataRemark = (<ReactJson name='detail' src={objConverter} displayDataTypes={false} displayObjectSize={false} enableClipboard={false} collapsed style={{
            textAlign: 'left'
          }} />)
        } else {
          dataRemark = remark
        }
        return (<span>
          <RemarksDiv key={remark} color={APP_COLORS.primary}>
            {dataRemark}
          </RemarksDiv>
        </span>)
      }
    }, {
      title: 'Created At',
      key: 'created_at',
      dataIndex: 'created_at',
      render: value => moment.utc(value, 'DD/MM/YYYY HH:mm:ss').tz('Asia/Jakarta').format('DD/MM/YYYY HH:mm:ss'),
      width: '15%',
    }, {
      title: 'Created By',
      key: 'created_by',
      dataIndex: 'created_by',
      width: '15%',
      render: (_, row) => get(row, 'added_by_name') || get(row, 'created_by')
    }, {
      title: 'From Status',
      key: 'from_status',
      dataIndex: 'from_status',
      width: '20%',
    }, {
      title: 'To Status',
      key: 'to_status',
      dataIndex: 'to_status',
      width: '20%',
    }]

    return (
      <RemarkStyle>
        <Header content='REMARKS' />
        <Table
          dataSource={remarks.reverse()}
          columns={columns}
          rowKey={(_, index) => index}
          scroll={{
            x: true
          }}
        />
      </RemarkStyle>
    )
  }
}

export default Remarks
