import React, { useState } from "react";
import { Modal, Button } from "antd";
import {
  RollbackOutlined,
  ZoomInOutlined,
  ZoomOutOutlined,
  CloseOutlined,
  LeftOutlined,
  RightOutlined,
} from "@ant-design/icons";

const Viewer = ({ visible, imageUrl, onClose, items = [], index = 0, onPrev, onNext }) => {
  const [rotation, setRotation] = useState(0);
  const [scale, setScale] = useState(1);

  const handleRotateLeft = () => setRotation((prev) => prev - 90);
  const handleRotateRight = () => setRotation((prev) => prev + 90);
  const handleZoomIn = () => setScale((prev) => prev + 0.2);
  const handleZoomOut = () => setScale((prev) => Math.max(0.2, prev - 0.2));

  return (
    <Modal
      visible={visible}
      footer={null}
      onCancel={onClose}
      destroyOnClose
      width="80%"
      bodyStyle={{
        textAlign: "center",
        background: "#FFF",
        padding: 0,
        overflow: 'hidden'
      }}
      closable
      closeIcon={<CloseOutlined style={{ color: "black" }} />}
    >
      {/* Image wrapper */}
      <div
        style={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          minHeight: "80vh",
          overflow: "hidden",
          width: '100%'
        }}
      >
        <div style={{ maxWidth: '100%', maxHeight: '80vh', overflow: 'hidden', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
          <img
            src={imageUrl}
            alt="document"
            style={{
              display: 'block',
              transform: `rotate(${rotation}deg) scale(${scale})`,
              transformOrigin: "center center",
              transition: "transform 0.3s ease",
              maxWidth: "100%",
              maxHeight: "100%",
              objectFit: 'contain'
            }}
          />
        </div>
      </div>

      {/* Toolbar */}
      <div
        style={{
          textAlign: "center",
          marginTop: 10,
          display: "flex",
          justifyContent: "center",
          gap: "10px",
          alignItems: 'center'
        }}
      >
        <Button icon={<LeftOutlined />} onClick={onPrev} disabled={!items || index <= 0} />
        <Button icon={<RightOutlined />} onClick={onNext} disabled={!items || index >= (items.length - 1)} />
        <div style={{ minWidth: 80, textAlign: 'center' }}>{items && items.length ? `${index + 1} / ${items.length}` : ''}</div>
        <Button icon={<ZoomInOutlined />} onClick={handleZoomIn} />
        <Button icon={<ZoomOutOutlined />} onClick={handleZoomOut} />
        <Button icon={<RollbackOutlined />} onClick={handleRotateLeft} />
        <Button
          icon={<RollbackOutlined style={{ transform: "scaleX(-1)" }} />}
          onClick={handleRotateRight}
        />
      </div>
    </Modal>
  );
};

export default Viewer;
