import React, { Component } from 'react'
import { Table } from 'antd'
import moment from 'moment-timezone'

import { Header } from '../../../../../components/StyledComponents'
import { TransactionDetailStyle } from './component.style'


class TransactionDetailSection extends Component {
  render() {
    const { transactions } = this.props
    const columns = [{
      title: 'Amount',
      key: 'amount',
      dataIndex: 'amount'
    }, {
      title: 'Created At',
      key: 'created_at',
      dataIndex: 'created_at',
      render: value => value && moment.utc(value, 'DD/MM/YYYY HH:mm:ss').tz('Asia/Jakarta').format('DD/MM/YYYY HH:mm:ss')
    }, {
      title: 'Paid by',
      key: 'paid_by',
      dataIndex: 'paid_by'
    }, {
      title: 'Payment mode',
      key: 'payment_mode',
      dataIndex: 'payment_mode',
      render: value => value === "['cheque']" ? 'cheque' : value
    }, {
      title: 'Status',
      key: 'status',
      dataIndex: 'status'
    }, {
      title: 'Completion Date',
      key: 'completion_date',
      dataIndex: 'completion_date',
      render: value => value && moment(value).tz('Asia/Jakarta').format('DD/MM/YYYY')
    }, {
      title: 'Transaction id',
      key: 'transaction_id',
      dataIndex: 'transaction_id'
    }]

    return (
      <TransactionDetailStyle>
        <Header content='TRANSACTIONS DETAIL' />
        <Table
          dataSource={transactions}
          columns={columns}
          rowKey='id'
          scroll={{
            x: true
          }}
        />
      </TransactionDetailStyle>
    )
  }
}

export default TransactionDetailSection
