import React from 'react'
import moment from 'moment-timezone'
import { Input, Select, DatePicker, TimePicker, Switch, Typography, Upload, Checkbox, Button, message, notification } from 'antd'
import { LoadingOutlined, PlusOutlined } from '@ant-design/icons'
import { get } from 'lodash'
import { CarSketch } from '../../../../../components'

const { Option } = Select

function getBase64(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.readAsDataURL(file)
    reader.onload = () => resolve(reader.result)
    reader.onerror = error => reject(error)
  })
}

const dummyRequest = ({ file, onSuccess, onError }) => {
  setTimeout(() => {
    onSuccess('ok')
  }, 100) // Small delay to simulate upload
}

class FieldRenderer {
  constructor(props) {
    this.props = props
    this.state = {
      currentFileUploadField: null,
      filePreview: {},
      uploadedFiles: {},
      signedUrls: {},
      fieldLoadingStates: {},
      fieldUploadIds: {},
      fieldUploadContexts: {}
    }
  }

  // Set loading state for specific field
  setFieldLoading = (fieldName, isLoading, uploadId = null) => {
    this.state.fieldLoadingStates = {
      ...this.state.fieldLoadingStates,
      [fieldName]: isLoading
    }
    
    if (uploadId) {
      this.state.fieldUploadIds = {
        ...this.state.fieldUploadIds,
        [fieldName]: uploadId
      }
    }
  }

  // Stage context for an upload, called from parent (form.js)
  stageUploadContext = (fieldName, updateFieldValue, isMultiple, currentValue, file, uploadId, preview) => {
    const fileUid = file.uid || `${file.name}-${Date.now()}` // Use consistent UID for context
    this.setFieldLoading(fieldName, true, uploadId)
    this.state.fieldUploadContexts[fieldName] = {
      updateFieldValue,
      isMultiple,
      currentValue,
      fileUid,
      uploadId,
      preview
    }
    this.state.currentFileUploadField = fieldName
    this.state.currentUpdateFieldValue = updateFieldValue
    this.state.currentIsMultiple = isMultiple
    this.state.currentValue = currentValue
    this.state.currentFileUid = fileUid
    this.state.currentUploadId = uploadId
  }

  // Get loading state for specific field
  isFieldLoading = (fieldName) => {
    return this.state.fieldLoadingStates[fieldName] || false
  }

  formatNumber = (value) => {
    // Remove all non-digits
    const numbersOnly = value.replace(/\D/g, '')
    // Add thousand separators
    return numbersOnly.replace(/\B(?=(\d{3})+(?!\d))/g, ',')
  }

  handleClaimAmountChange = (e, updateFieldValue) => {
    const inputValue = e.target.value
    const numbersOnly = inputValue.replace(/\D/g, '')
    // Store the raw number without commas
    updateFieldValue(numbersOnly)
  }

  handleNikChange = (e, updateFieldValue) => {
    const inputValue = e.target.value
    // Only allow numbers and limit to 16 digits
    const numbersOnly = inputValue.replace(/\D/g, '').slice(0, 16)
    updateFieldValue(numbersOnly)
  }

  createDisabledDateFunction = (attributeData) => {
    const { calendar_date_end_on, calendar_date_starting_from } = attributeData
    
    return (current) => {
      if (!current) return false
      
      const hasStartDate = calendar_date_starting_from && calendar_date_starting_from !== null
      const hasEndDate = calendar_date_end_on && calendar_date_end_on !== null
      
      // If both dates exist, allow only dates between them
      if (hasStartDate && hasEndDate) {
        const startDate = moment(calendar_date_starting_from)
        const endDate = moment(calendar_date_end_on)
        return current.isBefore(startDate, 'day') || current.isAfter(endDate, 'day')
      }
      
      // If only start date exists, disable dates before it
      if (hasStartDate && !hasEndDate) {
        const startDate = moment(calendar_date_starting_from)
        return current.isBefore(startDate, 'day')
      }
      
      // If only end date exists, disable dates after it
      if (!hasStartDate && hasEndDate) {
        const endDate = moment(calendar_date_end_on)
        return current.isAfter(endDate, 'day')
      }
      
      // If neither exists, no restrictions
      return false
    }
  }

  handleImageUpload = async (info, fieldName, updateFieldValue, isMultiple = false, currentValue = null) => {
    if (info.file.status === 'uploading') {
      const { onMultiUpload } = this.props

       if (isMultiple && onMultiUpload) {
         const files = (info.fileList || [])
           .filter(f => f.originFileObj)
         if (files.length > 0) {
           onMultiUpload(files, fieldName, updateFieldValue, isMultiple, currentValue)
         }
         return
       }

      // single-file path
      if (this.isFieldLoading(fieldName)) {
        return
      }
      const acceptedFileType = ['image/jpeg', 'image/jpg', 'image/png', 'application/pdf']
      const isLt10KB = info.file.size / 1024 / 1024 < 0.01
      const isGt10MB = info.file.size / 1024 / 1024 > 10
      
      if (isLt10KB) {
        message.error('Photo terlalu kecil, min 10kb')
        return
      }
      if (isGt10MB) {
        message.error('Photo terlalu besar, max 10mb')
        return
      }
      
      if (acceptedFileType.includes(info.file.type) && !isLt10KB && !isGt10MB) {
        try {
          const { file } = info
          const formData = {}
          formData['name'] = file.name
          formData['type'] = file.type

          const actualFile = file.originFileObj || file
          const base64Preview = await getBase64(actualFile)

          const filePreview = {
            ...this.state.filePreview,
            [`${fieldName}_${file.uid}`]: base64Preview
          }
          this.state.filePreview = filePreview

          const uploadId = `${fieldName}_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`

          this.setFieldLoading(fieldName, true, uploadId)

          this.state.fieldUploadContexts[fieldName] = {
            updateFieldValue,
            isMultiple,
            currentValue,
            fileUid: file.uid,
            uploadId,
            file: actualFile,
            name: file.name,
            preview: base64Preview
          }

          this.state.currentFileUploadField = fieldName
          this.state.currentUpdateFieldValue = updateFieldValue
          this.state.currentIsMultiple = isMultiple
          this.state.currentValue = currentValue
          this.state.currentFileUid = file.uid
          this.state.currentUploadId = uploadId

          if (this.props.generateSignedUrl) {
            this.props.generateSignedUrl({
              body: { formData },
              uploadedFile: actualFile,
              fieldName: fieldName,
              uploadId: uploadId
            })
          }

        } catch (error) {
          message.error('Ada yang bermasalah, reload dan ulangi kembali')
        }
      } else {
        notification['error']({ message: 'Check your file type. Only JPG, JPEG, PNG, and PDF are allowed.' })
      }
    }
  }

  clearUploadFailure = (fieldName, uploadId) => {
    const s = this.state
    Object.keys(s.fieldLoadingStates || {}).forEach(key => {
      const kf = key.split(':').pop()
      if (kf === fieldName || key === fieldName) s.fieldLoadingStates[key] = false
    })
    Object.keys(s.fieldUploadContexts || {}).forEach(key => {
      const kf = key.split(':').pop()
      if (kf === fieldName || key === fieldName) delete s.fieldUploadContexts[key]
    })
    if (uploadId && s.currentUploadId === uploadId) {
      s.currentFileUploadField = null
      s.currentUpdateFieldValue = null
      s.currentIsMultiple = false
      s.currentValue = null
      s.currentFileUid = null
      s.currentUploadId = null
    }
  }

  updateSignedUrl = (signedUrl, fieldName = null, uploadId = null) => {
    const targetField = fieldName || this.state.currentFileUploadField
    const targetContext = this.state.fieldUploadContexts[targetField]

    if (uploadId && targetContext && targetContext.uploadId !== uploadId) {
      return
    }

    if (signedUrl && targetField && (targetContext || this.state.currentUpdateFieldValue)) {
      const updateFieldValue = targetContext?.updateFieldValue || this.state.currentUpdateFieldValue
      const isMultiple = targetContext?.isMultiple ?? this.state.currentIsMultiple
      const currentValue = targetContext?.currentValue ?? this.state.currentValue
      const fileUid = targetContext?.fileUid || this.state.currentFileUid
      const url = get(signedUrl, 'url')

      if (url) {
        const currentFilePreviewKey = `${targetField}_${fileUid}`
        const base64Preview = this.state.filePreview[currentFilePreviewKey] || targetContext?.preview

        if (base64Preview) {
          const fieldForPreview = targetField.includes(':') ? targetField.split(':').slice(1).join(':') : targetField
          const urlPreviewKey = `url_${url.split('/').pop()}_${fieldForPreview}`
          this.state.filePreview = {
            ...this.state.filePreview,
            [urlPreviewKey]: base64Preview
          }
        }

        if (isMultiple) {
          const existingUrls = currentValue && Array.isArray(currentValue) ?
            currentValue.filter(item => typeof item === 'string') : []
          if (!existingUrls.includes(url)) {
            existingUrls.push(url)
          }
          updateFieldValue(existingUrls)
        } else {
          updateFieldValue(url)
        }

        this.setFieldLoading(targetField, false)
        delete this.state.fieldUploadContexts[targetField]

        if (this.state.currentFileUploadField === targetField) {
          this.state.currentFileUploadField = null
          this.state.currentUpdateFieldValue = null
          this.state.currentIsMultiple = false
          this.state.currentValue = null
          this.state.currentFileUid = null
          this.state.currentUploadId = null
        }
      }
    }
  }

  renderBooleanField = (currentValue, updateFieldValue) => {
    return (
      <Switch
        checked={currentValue === true || currentValue === 'true'}
        onChange={(checked) => updateFieldValue(checked)}
        checkedChildren="Yes"
        unCheckedChildren="No"
      />
    )
  }

  renderCheckboxField = (currentValue, updateFieldValue, label) => {
    return (
      <Checkbox
        checked={currentValue || false}
        onChange={(e) => updateFieldValue(e.target.checked)}
      >
        {label}
      </Checkbox>
    )
  }

  renderChoicesField = (currentValue, updateFieldValue, options, label, isRequired = false, submitAttempted = false, attributeData = {}) => {
    const selectStyle = {
      width: '100%',
      ...(isRequired && !currentValue && submitAttempted ? { borderColor: '#ff4d4f' } : {})
    }
    
    return (
      <Select
        showSearch
        placeholder={`Pilih ${label}${isRequired ? ' *' : ''}`}
        allowClear
        value={currentValue}
        onChange={(value) => updateFieldValue(value)}
        style={selectStyle}
        loading={attributeData.loading}
        dropdownMatchSelectWidth={false}
        dropdownStyle={{ minWidth: '400px' }}
        filterOption={(input, option) =>
          option.children.toLowerCase().indexOf(input.toLowerCase()) >= 0
        }
        optionFilterProp="children"
      >
        {
          options.map((option, index) => (
            <Option key={index} value={option[0]}>
              {option[1]}
            </Option>
          ))
        }
      </Select>
    )
  }

  renderChoicesExternalField = (currentValue, updateFieldValue, options, label) => {
    const { choicesData = [], choicesDataLoading, handleChoicesExternalChange } = this.props
    
    return (
      <Select
        showSearch
        key={label}
        placeholder={`Pilih ${label}`}
        loading={!!choicesDataLoading}
        notFoundContent="Ketik dan cari (3 karakter atau lebih)"
        optionFilterProp="children"
        allowClear
        value={currentValue}
        dropdownMatchSelectWidth={false}
        onSearch={value => handleChoicesExternalChange(value, options[0])}
        onSelect={value => updateFieldValue(value)}
        filterOption={(input, option) =>
          option.children.toLowerCase().indexOf(input.toLowerCase()) >= 0
        }
      >
        {
          choicesData.map((data = {}) => (
            <Option
              key={data.code}
              value={JSON.stringify(data)}
            >
              {`${data.name} (${data.code})`}
            </Option>
          ))
        }
      </Select>
    )
  }

  renderYearField = (currentValue, updateFieldValue, label) => {
    return (
      <DatePicker
        picker="year"
        placeholder={`Pilih ${label}`}
        value={currentValue ? moment(currentValue, 'YYYY') : null}
        onChange={(date, dateString) => updateFieldValue(dateString)}
      />
    )
  }

  renderDateField = (currentValue, updateFieldValue, label, attributeData, isRequired = false, submitAttempted = false) => {
    const disabledDate = this.createDisabledDateFunction(attributeData)
    const dateStyle = isRequired && !currentValue && submitAttempted ? { borderColor: '#ff4d4f' } : {}
    
    return (
      <DatePicker
        placeholder={`Pilih ${label}${isRequired ? ' *' : ''}`}
        value={currentValue ? moment(currentValue) : null}
        onChange={(date) => updateFieldValue(date ? moment(date).format('YYYY-MM-DD') : null)}
        format="DD-MM-YYYY"
        disabledDate={disabledDate}
        style={dateStyle}
      />
    )
  }

  renderTimeField = (currentValue, updateFieldValue, label) => {
    return (
      <TimePicker
        placeholder={`Pilih ${label}`}
        value={currentValue ? moment(currentValue, 'HH:mm') : null}
        onChange={(time, timeString) => updateFieldValue(timeString)}
        format="HH:mm"
        use12Hours={false}
      />
    )
  }

  renderSketchField = (currentValue, updateFieldValue, label) => {
    const { generateSignedUrl } = this.props
    
    return (
      <div>
        <CarSketch
          value={currentValue}
          onChange={updateFieldValue}
          generateSignedUrl={generateSignedUrl}
          signedUrl={this.props.signedUrl}
        />
        <Typography.Text type="secondary" style={{ marginTop: 8, display: 'block' }}>
          Click on the car diagram to add X marks on damaged parts. Click a mark again to remove it.
        </Typography.Text>
      </div>
    )
  }

  renderImageField = (currentValue, updateFieldValue, onPreview, fieldName, attributeData = {}, isRequired = false, submitAttempted = false) => {
    const { is_multiple_value_required = false } = attributeData
    const { pendingUploads = {}, failedUploads = {}, retryUpload, formName } = this.props
    const identifier = formName ? `${formName}:${fieldName}` : fieldName
    const pendingItems = pendingUploads[identifier] || []
    const failedItems = failedUploads[identifier] || []

    const uploadButton = (
      <div>
        {this.isFieldLoading(fieldName) ? <LoadingOutlined /> : <PlusOutlined />}
        <div style={{ marginTop: 8 }}>
          Upload{isRequired ? ' *' : ''}
        </div>
      </div>
    )

    const convertUrlToFileObject = (item, index) => {
      if (typeof item === 'string') {
        const rawFilename = item.split('/').pop()
        const previewKey = `url_${rawFilename}_${fieldName}`
        const storedBase64Preview = this.state.filePreview[previewKey]
        return {
          uid: `url-${item}`,
          name: rawFilename || `image-${index + 1}.jpg`,
          status: 'done',
          url: storedBase64Preview || item,
          thumbUrl: storedBase64Preview || item,
          actualUrl: item,
          response: { url: item }
        }
      }
      if (item.url || item.thumbUrl) return item
      const previewKey = `${fieldName}_${item.uid}`
      const storedPreview = this.state.filePreview[previewKey]
      return {
        ...item,
        url: storedPreview || item.url,
        thumbUrl: storedPreview || item.thumbUrl
      }
    }

    const rawFileList = currentValue ? (Array.isArray(currentValue) ? currentValue : [currentValue]) : []
    const fileList = rawFileList.map(convertUrlToFileObject)
    const showUploadButton = is_multiple_value_required || fileList.length === 0

    return (
      <div>
        <Upload
          name="avatar"
          listType="picture-card"
          fileList={fileList}
          multiple={is_multiple_value_required}
          onChange={(info) => {
            this.handleImageUpload(info, fieldName, updateFieldValue, is_multiple_value_required, currentValue)
          }}
          customRequest={dummyRequest}
          disabled={this.isFieldLoading(fieldName)}
          accept='.jpg, .jpeg, .png, .pdf'
          showUploadList={{
            showPreviewIcon: true,
            showRemoveIcon: true,
            showDownloadIcon: false
          }}
          onRemove={(file) => {
            const urlToRemove = file.actualUrl || file.response?.url || file.url
            if (!urlToRemove) return
            if (Array.isArray(currentValue)) {
              const newFileList = currentValue.filter((item) => {
                if (typeof item === 'string') return item !== urlToRemove
                if (item && typeof item === 'object') return item.uid !== file.uid
                return true
              })
              updateFieldValue(newFileList.length > 0 ? newFileList : null)
            } else if (typeof currentValue === 'string') {
              if (currentValue === urlToRemove) updateFieldValue(null)
            } else {
              updateFieldValue(null)
            }
          }}
          onPreview={(file) => {
            if (onPreview) onPreview(file.url || file.thumbUrl, file.name, file.type)
          }}
        >
          {showUploadButton && uploadButton}
        </Upload>

        {pendingItems.length > 0 && (
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px', marginTop: '8px' }}>
            {pendingItems.map((item) => (
              <div
                key={item.uid}
                style={{
                  width: 104,
                  height: 104,
                  border: '1px solid #d9d9d9',
                  borderRadius: 2,
                  position: 'relative',
                  overflow: 'hidden',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  background: '#fafafa'
                }}
              >
                {item.preview && (
                  <img
                    src={item.preview}
                    alt={item.name}
                    style={{ width: '100%', height: '100%', objectFit: 'cover', opacity: 0.5 }}
                  />
                )}
                <div style={{
                  position: 'absolute',
                  top: 0, left: 0, right: 0, bottom: 0,
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  justifyContent: 'center'
                }}>
                  <LoadingOutlined style={{ fontSize: 20, color: '#1890ff' }} />
                  <div style={{ fontSize: 11, color: '#1890ff', marginTop: 4, textAlign: 'center', padding: '0 4px', wordBreak: 'break-all' }}>
                    {item.name}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {failedItems.length > 0 && (
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px', marginTop: '8px' }}>
            {failedItems.map((item) => (
              <div
                key={item.uid}
                style={{
                  width: 104,
                  height: 104,
                  border: '1px solid #ff4d4f',
                  borderRadius: 2,
                  position: 'relative',
                  overflow: 'hidden',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  background: '#fff2f0'
                }}
              >
                {item.preview && (
                  <img
                    src={item.preview}
                    alt={item.name}
                    style={{
                      width: '100%',
                      height: '100%',
                      objectFit: 'cover',
                      opacity: 0.5,
                      filter: 'grayscale(100%)'
                    }}
                  />
                )}
                <div style={{
                  position: 'absolute',
                  top: 0, left: 0, right: 0, bottom: 0,
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  justifyContent: 'center'
                }}>
                  <Button
                    size="small"
                    type="primary"
                    danger
                    onClick={() => retryUpload && retryUpload(item, identifier)}
                    style={{ zIndex: 1 }}
                  >
                    Retry
                  </Button>
                  <div style={{ fontSize: 11, color: '#ff4d4f', marginTop: 4, textAlign: 'center', padding: '0 4px', wordBreak: 'break-all' }}>
                    {item.name}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        <div style={{ marginTop: '8px' }}>
          {currentValue ? (
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <Typography.Text type="secondary">
                {Array.isArray(currentValue) ? `${currentValue.length} image(s)` : '1 image'} uploaded
                {is_multiple_value_required && ' (Multiple files allowed)'}
              </Typography.Text>
              <Button
                type="text"
                size="small"
                danger
                onClick={() => updateFieldValue(null)}
                style={{ fontSize: '12px', padding: '2px 6px' }}
              >
                Clear All
              </Button>
            </div>
          ) : (
            <Typography.Text type="secondary" style={{ fontSize: '12px' }}>
              {is_multiple_value_required
                ? 'Click + to add multiple images'
                : 'Click + to upload an image'}
            </Typography.Text>
          )}
        </div>
        {isRequired && !currentValue && submitAttempted && (
          <Typography.Text type="danger" style={{ fontSize: '12px', marginTop: '4px', display: 'block' }}>
            * This field is required
          </Typography.Text>
        )}
      </div>
    )
  }

  renderDisclaimerField = (currentValue, updateFieldValue) => {
    return (
      <Typography.Paragraph>
        <Checkbox
          checked={currentValue || false}
          onChange={(e) => updateFieldValue(e.target.checked)}
        >
          I agree to the terms and conditions
        </Checkbox>
      </Typography.Paragraph>
    )
  }

  renderAsteriskField = (currentValue, updateFieldValue, label) => {
    return (
      <div>
        <Input
          placeholder={`Enter ${label}`}
          value={currentValue}
          onChange={(e) => updateFieldValue(e.target.value)}
        />
        <Typography.Text type="secondary">* Required field</Typography.Text>
      </div>
    )
  }

  renderClaimAmountField = (currentValue, updateFieldValue, label) => {
    return (
      <Input
        placeholder={`Enter ${label}`}
        value={currentValue ? this.formatNumber(currentValue) : ''}
        onChange={(e) => this.handleClaimAmountChange(e, updateFieldValue)}
        addonBefore="Rp"
      />
    )
  }

  renderNikNumberField = (currentValue, updateFieldValue, label) => {
    return (
      <div>
        <Input
          placeholder={`Enter ${label} (16 digits)`}
          value={currentValue || ''}
          onChange={(e) => this.handleNikChange(e, updateFieldValue)}
          maxLength={16}
        />
        {currentValue && currentValue.length !== 16 && (
          <Typography.Text type="danger" style={{ fontSize: '12px' }}>
            NIK must be exactly 16 digits ({currentValue.length}/16)
          </Typography.Text>
        )}
        {currentValue && currentValue.length === 16 && (
          <Typography.Text type="success" style={{ fontSize: '12px' }}>
            ✓ Valid NIK format
          </Typography.Text>
        )}
      </div>
    )
  }

  renderStringField = (currentValue, updateFieldValue, label, isRequired = false, submitAttempted = false) => {
    const inputStyle = isRequired && !currentValue && submitAttempted ? { borderColor: '#ff4d4f' } : {}
    
    return (
      <Input
        placeholder={`Enter ${label}${isRequired ? ' *' : ''}`}
        value={currentValue}
        onChange={(e) => updateFieldValue(e.target.value)}
        style={inputStyle}
      />
    )
  }

  render(type, name, currentValue, updateFieldValue, label, options = [], attributeData = {}, isRequired = false, submitAttempted = false) {
    switch (type) {
      case 'boolean':
        return this.renderBooleanField(currentValue, updateFieldValue)

      case 'checkbox':
        return this.renderCheckboxField(currentValue, updateFieldValue, label)

      case 'choices':
        return this.renderChoicesField(currentValue, updateFieldValue, options, label, isRequired, submitAttempted, attributeData)

      case 'choices_external':
        return this.renderChoicesExternalField(currentValue, updateFieldValue, options, label)

      case 'year':
        return this.renderYearField(currentValue, updateFieldValue, label)

      case 'date':
        return this.renderDateField(currentValue, updateFieldValue, label, attributeData, isRequired, submitAttempted)

      case 'time':
        return this.renderTimeField(currentValue, updateFieldValue, label)

      case 'sketch':
        return this.renderSketchField(currentValue, updateFieldValue, label)

      case 'image':
        return this.renderImageField(currentValue, updateFieldValue, this.props.onImagePreview, name, attributeData, isRequired, submitAttempted)

      case 'disclaimer':
        return this.renderDisclaimerField(currentValue, updateFieldValue)

      case 'asterisk':
        return this.renderAsteriskField(currentValue, updateFieldValue, label)

      case 'string':
      default:
        // Special handling for specific field names
        if (name === 'claim_amount') {
          return this.renderClaimAmountField(currentValue, updateFieldValue, label)
        }
        
        if (name === 'nik_number') {
          return this.renderNikNumberField(currentValue, updateFieldValue, label)
        }
        
        // Default string input for other fields
        return this.renderStringField(currentValue, updateFieldValue, label, isRequired, submitAttempted)
    }
  }
}

export default FieldRenderer