import React, { Component} from 'react';
import { Button, Modal } from 'antd';
import { pdfjs } from "react-pdf"
import { ImageComponentStyle } from './component.style';
import PdfViewerModal from './PdfViewerModal';

pdfjs.GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjs.version}/pdf.worker.js`

class ImageComponent extends Component {
  state = {
    showViewImageButton: false,
    isModalVisible: false,
    imageModalVisible: false,
  };

  handleOpenModal = () => {
    this.setState({ isModalVisible: true });
  };

  handleCloseModal = () => {
    this.setState({ isModalVisible: false });
  };

  handleOpenImageModal = () => {
    this.setState({ imageModalVisible: true });
  };

  handleCloseImageModal = () => {
    this.setState({ imageModalVisible: false });
  };
  

  render() {
    const { value } = this.props;
    const { showViewImageButton, isModalVisible } = this.state;
    
    
    // Handle array values - take the first element
    let actualValue = value;
    if (Array.isArray(value) && value.length > 0) {
      actualValue = value[0];
    }
    
    // Check if actualValue is a valid string before trying to split
    const fileExtension = actualValue && typeof actualValue === 'string' ? actualValue.split('.').pop() : null;
    return (
      <ImageComponentStyle>
        {/* Only render if actualValue is a valid string */}
        {!actualValue || typeof actualValue !== 'string' ? (
          <div style={{ color: '#999', fontStyle: 'italic' }}>No document available</div>
        ) : fileExtension === 'pdf' ? (
          <>
            <Button type="primary" onClick={this.props.onClickImage ? () => this.props.onClickImage(actualValue) : this.handleOpenModal}>
              View Document
            </Button>
            <PdfViewerModal
              visible={isModalVisible}
              onClose={this.handleCloseModal}
              fileUrl={actualValue}
            />
          </>
        ) : showViewImageButton ? (
          <a href={actualValue} target="_blank" rel="noopener noreferrer">
            View Document
          </a>
        ) : (
          <img
            alt="document"
            src={actualValue}
            onClick={() => this.props.onClickImage ? this.props.onClickImage(actualValue) : this.handleOpenImageModal()}
            onError={() => this.setState({ showViewImageButton: true })}
            width={this.props.width || 'auto'}
            height={this.props.height || 10}
            style={this.props.style}
            className={this.props.className || 'img'}
          />

        )}
        { /* Image preview modal (for images only) */ }
        <Modal
          visible={this.state.imageModalVisible}
          footer={null}
          onCancel={this.handleCloseImageModal}
          width={800}
        >
          <div style={{ textAlign: 'center' }}>
            <img src={actualValue} alt="preview" style={{ maxWidth: '100%', maxHeight: '80vh' }} />
          </div>
        </Modal>
      </ImageComponentStyle>
    );
  }
}

export default ImageComponent;
