import React, { Component } from 'react'
import { Tag, Row } from 'antd'
import { get } from 'lodash'

import { ClaimDetailsStyle } from './component.style'
import { Header, DisplayKeyValue } from '../../../../../components/StyledComponents'
import { capitaliseFirstCharacter } from '../../../../../helpers/capitiliseFirstCharacter'
import { getClaimAmountWithCurrency } from '../../../../../helpers/getClaimAmountWithCurrency'

const getColor = (status) => {
  switch (status) {
    case 'VERIFIED':
      return '#0d4221'
    case 'FRAUD_SUSPECT':
      return '#FFC800'
    case 'FRAUD_CONFIRM':
      return '#FF0000'
    default:
      return '#000000'
  }
}



const serviceCenterTitle = [
  {
    dataIndex: 'service_center_repair_quoatation',
    title: 'Service Center Repair Quotation',
    link: true
  }, {
    dataIndex: 'service_center_repair_final_invoice',
    title: 'Service Center Repair Final Invoice',
    link: true
  }, {
    dataIndex: 'service_center_customer_deductible',
    title: 'Service Center Customer Deductible',
    type: 'amount'
  }, {
    dataIndex: 'service_center_cancellation_fee',
    title: 'Service Center Cancellation Fee',
    type: 'amount'
  }, {
    dataIndex: 'service_center_total_spare_part_cost',
    title: 'Service Center Total Spare Part Cost',
    type: 'amount'
  }, {
    dataIndex: 'service_center_delivery_cost',
    title: 'Service Center Delivery Cost',
    type: 'amount'

  }, {
    dataIndex: 'service_center_vat',
    title: 'Service Center Vat',
    type: 'amount'
  }, {
    dataIndex: 'service_center_pickup_airwaybill_number',
    title: 'Service Center Pickup Airwaybill Number'
  }, {
    dataIndex: 'service_center_delivery_airwaybill_number',
    title: 'Service Center Delivery Airwaybill Number',
  }, {
    dataIndex: 'service_center_inhouse_repiar_cost',
    title: 'Service Center Inhouse/external Repiar Cost',
    type: 'amount'
  }, {
    dataIndex: 'service_center_cancellation_fee_invoice',
    title: 'Service Center Cancellation Fee Invoice',
    link: true
  },{
    dataIndex: 'service_center_service_cost',
    title: 'Service Center Service Cost'
  }, {
    dataIndex: 'service_center_beyond_economic_repair',
    title: 'Service Center Beyond Economic Repair'
  }, {
    dataIndex: 'service_center_ber_invoice',
    title: 'Service Center Beyond Economic Repair Invoice',
    link: true
  }
]
class ClaimDetails extends Component {
  getStatusColor = (statusDisplayName) => {
    // Define colors based on status display names
    const statusColors = {
      'Pending': '#FFC800',           // Yellow/Orange
      'Approved': '#87d068',          // Green  
      'Rejected': '#f50',             // Red
      'Under Review': '#2db7f5',      // Blue
      'Submitted': '#108ee9',         // Default Blue
      'Draft': '#d9d9d9',            // Gray
      'Cancelled': '#ff4d4f',        // Red
      'Completed': '#52c41a',        // Bright Green
      'In Progress': '#1890ff',       // Blue
      // Add more status mappings as needed
    }
    
    return statusColors[statusDisplayName] || '#108ee9' // Default blue if status not mapped
  }

  componentDidUpdate(prevProps) {
    const { claimDetails = {} } = this.props
    const { claimDetails: prevClaimDetails = {} } = prevProps
    
    const currentStatus = get(claimDetails, 'status.display_name')
    const previousStatus = get(prevClaimDetails, 'status.display_name')
    
    // Check if status display_name has changed
    if (currentStatus && previousStatus && currentStatus !== previousStatus) {
      
      this.forceUpdate()
    }
  }

  render() {
    const { claimDetails = {} } = this.props
    const {
      status,
      claim_no: claimNo,
      application_no: applicationNo,
      policy_number: policyNumber,
      partner_id: partnerID,
      display_name: productDisplayName,
      product_key: productKey,
      benefit,
      package_name: packageName,
      provider_claim_id: providerClaimID,
      policy_ref_number: policyReferenceNumber,
      claim_amount: claimAmount,
      user_status: fraudStatus,
      package_country: packageCountry
    } = claimDetails


    const serviceCenterDetails = serviceCenterTitle.map(({ title, dataIndex, link }) => {
      if (claimDetails[dataIndex] === null || claimDetails[dataIndex] === undefined) return null
      return (
        <DisplayKeyValue
          link={link}
          dataKey={title}
          value={claimDetails[dataIndex]}
        />
      )
    })


    return (
      <ClaimDetailsStyle>
        <Header content="CLAIM DETAIL" />
        <Row>
          <Tag color={this.getStatusColor(get(status, 'display_name', ''))}>STATUS: {get(status, 'display_name', '')}</Tag>
        </Row>
        <Row className='detail-container'>
          <DisplayKeyValue dataKey='Claim ID' value={claimNo} />
          <DisplayKeyValue dataKey='Application Number' value={applicationNo} />
          <DisplayKeyValue dataKey='Policy Number' value={policyNumber} />
          <DisplayKeyValue dataKey='Partner' value={packageName === 'Guard' && partnerID === 'ppagency' ? '-' : capitaliseFirstCharacter(partnerID)} />
          <DisplayKeyValue dataKey='Product key' value={productDisplayName || productKey} />
          <DisplayKeyValue dataKey='Benefit' value={benefit} />
          <DisplayKeyValue dataKey='Package Name' value={packageName} />
          <DisplayKeyValue dataKey='Provider claim ID' value={providerClaimID} />
          <DisplayKeyValue dataKey='Reference Id' value={policyReferenceNumber} />
          <DisplayKeyValue dataKey='Claim Amount' value={getClaimAmountWithCurrency(claimAmount ?? 0, packageCountry)} />
          {serviceCenterDetails},
          {
            fraudStatus ?
              <DisplayKeyValue dataKey='Fraud status' value={fraudStatus} color={getColor(fraudStatus)} />
              : null
          }
        </Row>
      </ClaimDetailsStyle>
    )
  }
}

export default ClaimDetails
