const strToObj = str => {
  try{
    let obj = {}
    if (str || typeof str === 'string') {
      var objStr = str.match(/\{(.)+\}/g)
      obj =  objStr
      // eval('obj =' + objStr) // eslint-disable-line
    }
    return obj
  } catch(e){
    const message = e.message
    return message
  }
  }
  
  export default strToObj
  