import { Table, Tag, Collapse } from 'antd'
import { CheckCircleFilled, CloseCircleFilled, ExclamationCircleFilled } from '@ant-design/icons'

const DataVerificationTable = ({ title = 'Verification', rows = [], variant = 'comparison' }) => {
  const isValidation = variant === 'validation'

  const getStatus = (isMatch) => {
    if (isMatch === true) {
      return {
        label: 'Match',
        icon: CheckCircleFilled,
        color: 'green',
        bgColor: 'rgba(82, 196, 26, 0.15)',
        rowBgColor: 'rgba(82, 196, 26, 0.1)'
      }
    }

    if (isMatch === false) {
      return {
        label: 'Not Match',
        icon: CloseCircleFilled,
        color: 'red',
        bgColor: 'rgba(245, 34, 45, 0.15)',
        rowBgColor: 'rgba(245, 34, 45, 0.1)'
      }
    }

    return {
      label: isValidation ? 'Waiting' : '',
      icon: ExclamationCircleFilled,
      color: 'orange',
      bgColor: 'rgba(250, 173, 20, 0.15)',
      rowBgColor: 'rgba(250, 173, 20, 0.1)'
    }
  }

  const columns = [
    {
      title: 'Data',
      dataIndex: 'label',
      key: 'label',
      render: (text) => <span style={{ fontWeight: 500 }}>{text}</span>
    },
    ...(isValidation
      ? [{
          title: 'Value',
          key: 'value',
          dataIndex: 'value',
        }]
      : [
          {
            title: 'OCR Claim',
            dataIndex: 'ocrValue',
            key: 'ocrValue',
            render: (text) => text || '-'
          },
          {
            title: 'Data Policy',
            dataIndex: 'policyValue',
            key: 'policyValue',
            render: (text) => text || '-'
          },
        ]
    ),
    {
      title: 'Status',
      key: 'status',
      align: 'right',
      render: (_, record) => {
        const status = getStatus(record.isMatch)
        const IconComp = status.icon
        return (
          <Tag
            color={status.color}
            style={{
              borderRadius: 12,
              padding: '2px 12px'
            }}
          >
            <IconComp style={{ marginRight: 4 }} />
            {status.label}
          </Tag>
        )
      }
    }
  ]

  return (
    <Collapse defaultActiveKey={['1']}>
      <Collapse.Panel key='1' header={title}>
        <Table
          columns={columns}
          dataSource={rows}
          rowKey='label'
          pagination={false}
          size='middle'
          bordered
          onRow={(record) => ({
            style: { backgroundColor: getStatus(record.isMatch).rowBgColor }
          })}
        />
      </Collapse.Panel>
    </Collapse>
  )
}

export default DataVerificationTable
