import { LoadingOutlined, PlusOutlined } from "@ant-design/icons"
import { Button, DatePicker, Form, Input, InputNumber, message, notification, Row, Select, Upload } from 'antd'
import { get } from 'lodash'
import React, { Component } from 'react'
import { connect } from 'react-redux'

import {
  ApproveButton, ButtonContainer, ChangeStatus, InfoContainer, RejectButton, Title,
  MultiBenefitAutoApprovalEventWrapper
} from './multiBenefitAutoApproval.style'

import errorActions from '../../../../../redux/error/actions'
import loadingActions from '../../../../../redux/loading/actions'
import claimsAction from '../../../../redux/claims/actions'



const { Option } = Select
const FormItem = Form.Item
const { TextArea } = Input

const { generateSignedUrl } = claimsAction
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

const dummyRequest = ({ _, onSuccess }) => {
  setTimeout(() => {
    onSuccess('ok')
  }, 0)
}

function getBase64(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.readAsDataURL(file)
    reader.onload = () => resolve(reader.result)
    reader.onerror = error => reject(error)
  })
}

class MultiBenefitAutoApprovalEvent extends Component {

  constructor(props) {
    super(props)
    this.state = {
      openCommentBox: {},
      selectedBenefit: [],
      payload: {},
      currentFileUploadBenefit: null,
      filePreview: {},
      signedUrls: {},
      multiBenefitAutoApprovalPayload: {}
    }
  }

  componentDidUpdate(prevprops) {
    const { signedUrl: prevSignedUrl } = prevprops
    const { signedUrl } = this.props

    const { currentFileUploadBenefit, signedUrls } = this.state

    if (prevSignedUrl !== signedUrl && currentFileUploadBenefit) {
      const url = get(signedUrl, 'url')
      const newSignedUrl = {
        ...this.state.signedUrls,
        [currentFileUploadBenefit]: {
          ...signedUrls[currentFileUploadBenefit],
          images: url || ''
        }
      }
      this.setState({ signedUrls: newSignedUrl })
    }
  }

  handleOnChangeSelect = (value, name, benefitKey) => {
    if (value !== 'other') {
      this['formRef' + benefitKey].current.setFieldsValue({ [name]: value })
      const newOpenCommentBoxState = {
        ...this.state.openCommentBox,
        [benefitKey]: false
      }

      this.setState({
        openCommentBox: newOpenCommentBoxState
      })
    } else {
      const newOpenCommentBoxState = {
        ...this.state.openCommentBox,
        [benefitKey]: true
      }
      this.setState({
        openCommentBox: newOpenCommentBoxState
      })
      this['formRef' + benefitKey].current.setFieldsValue({ [name]: undefined })
    }
  }

  uploadImage = async (info, benefitKey) => {
    this.setState({ currentFileUploadBenefit: benefitKey })
    if (info.file.status === 'done' || info.file.status === 'error') {
      const isLt10KB = info.file.size / 1024 / 1024 < 0.01
      const isGt10MB = info.file.size / 1024 / 1024 > 10
      if (isLt10KB) {
        message.error('Photo terlalu kecil, min 10kb')
        return
      }
      if (isGt10MB) {
        message.error('Photo terlalu besar, max 10mb')
        return
      }
      if ((info.file.type === 'image/jpeg' || info.file.type === 'image/jpg' || info.file.type === 'image/png') && !isLt10KB && !isGt10MB) {
        try {
          const { file } = info
          const formData = {}
          formData['name'] = file.name
          formData['type'] = file.type
          const filePreview = {
            ...this.state.filePreview,
            [benefitKey]: await getBase64(file.originFileObj)
          }
          const uploadedFile = file.originFileObj
          this.setState({ uploadLoader: true, filePreview })
          this.props.generateSignedUrl({
            body: {
              formData
            },
            uploadedFile
          })
        } catch (error) {
          message.error('Ada yang bermasalah, reload dan ulangi kembali')
        }
      } else {
        notification['error']({ message: 'Check your file type' })
      }
    }
  }


  renderAttribute = (type, label, name, options, value, benefitKey) => {
    const { generateSignedUrlLoading } = this.props
    const { openCommentBox, filePreview } = this.state


    const uploadButton = (
      <div>
        {generateSignedUrlLoading ? <LoadingOutlined /> : <PlusOutlined />}
        <div className='upload-button'>Upload</div>
      </div>
    )

    const getOptionValue = (options = [], value = "", benefitKey) => {
      const flag = options.some(([optionValue]) => optionValue === value)
      if (!flag) {
        return 'other'
      }
      return value
    }

    const getInputTextValue = () => {
      const flag = options.some(([optionValue]) => optionValue === value)
      if (flag) {
        return ''
      }
      return value
    }

    switch (type) {
      case 'choices':
        return (
          <div>
            <Select
              showSearch
              key={label}
              placeholder={`Select ${label}`}
              optionFilterProp="children"
              defaultValue={value ? getOptionValue(options, value, benefitKey) : options?.length === 1 ? options[0][0] : undefined}
              allowClear
              dropdownMatchSelectWidth={false}
              onChange={value => this.handleOnChangeSelect(value, name, benefitKey)}
              filterOption={(input, option) =>
                option.children.toLowerCase().indexOf(input.toLowerCase()) >= 0
              }
              disabled={options?.length === 1}
            >
              {options.map((option) => (
                <Option key={option[0]} value={option[0]}>
                  {option[1]}
                </Option>
              ))}
            </Select>
            {openCommentBox[benefitKey] && <TextArea className="other-textArea" id={'commentBox-' + benefitKey} defaultValue={getInputTextValue()} />}
          </div>
        )
      case "image":
        return <Upload
          name="avatar"
          listType="picture-card"
          onChange={(info) => this.uploadImage(info, benefitKey)}
          customRequest={dummyRequest}
          disabled={!!generateSignedUrlLoading}
          accept='.jpg, .jpeg, .png'
          showUploadList={false}
        >
          {
            filePreview[benefitKey]
              ?
              <img
                width="90%"
                src={filePreview[benefitKey]}
                alt="claim-document"
              />
              :
              uploadButton
          }
        </Upload>
      case 'date':
        return <DatePicker />
      case 'string':
      case 'text':
        if (name === 'amount') {
          return <InputNumber
            placeholder={`Enter ${label}`}
            formatter={value => `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ',')}
            parser={value => value.replace(/\$\s?|(,*)/g, '')}
            className='input-number'
          />
        } else {
          return <Input
            placeholder={`Enter ${label}`}
          />
        }
      default:
        return <Input
          key={label}
          placeholder={`Enter ${label}`}
        />
    }
  }


  approveOrRejectClickHandler = async (e, isApproved, benefitKey) => {
    e.preventDefault()
    const { openCommentBox, signedUrls } = this.state

    const valid = await this['formRef' + benefitKey].current.validateFields()
    if (!valid) {
      return
    }
    const payload = this['formRef' + benefitKey].current.getFieldsValue();

    if (openCommentBox[benefitKey]) {
      const comments = document.getElementById('commentBox-' + benefitKey).value
      if (comments !== '') { payload.remarks = comments } else {
        message.error('comments are required')
        this.setState({ submitEventLoader: false })
        return
      }
    }
    delete payload.images
    if (signedUrls[benefitKey]) {
      payload.images = signedUrls[benefitKey]?.images || ''
    }
    payload.is_approved = isApproved
    this.updateMultiBenefitAutoApproval(benefitKey, payload)
  }


  changeStatusClickHandler = (benefitKey) => {
    const { multiBenefitAutoApprovalPayload } = this.state
    const payload = {
      ...multiBenefitAutoApprovalPayload[benefitKey],
      is_approved: undefined
    }
    this.updateMultiBenefitAutoApproval(benefitKey, payload)
  }


  updateMultiBenefitAutoApproval = (benefit, payload) => {
    let newmultiBenefitAutoApprovalData = {
      ...this.state.multiBenefitAutoApprovalPayload,
      [benefit]: {
        ...payload
      }
    }
    this.setState({
      multiBenefitAutoApprovalPayload: newmultiBenefitAutoApprovalData
    })
  }

  selectOrDeselectBenefit = (benefitCode) => {
    const { selectedBenefit } = this.state

    if (selectedBenefit.includes(benefitCode)) {
      const newSelectedBenefit = selectedBenefit.filter((code) => benefitCode !== code)
      this.setState({
        selectedBenefit: newSelectedBenefit
      })
    } else {
      const newSelectedBenefit = [...selectedBenefit, benefitCode]
      this.setState({
        selectedBenefit: newSelectedBenefit
      })
    }
  }

  saveAutoApprovalFlow = () => {
    const { multiBenefitAutoApprovalPayload = {} } = this.state
    const { formData = {}, } = this.props
    const { multi_benefit_form_data: multiBenefitFormData = {} } = formData
    let autoApprovedCount = 0

    for (const benefitKey in multiBenefitFormData) {
      const { is_auto_approved: isAutoApproved } = multiBenefitFormData[benefitKey]
      if (!isAutoApproved) {
        autoApprovedCount++
      }
    }

    if(Object.keys(multiBenefitAutoApprovalPayload).length!== autoApprovedCount){
      notification.error({ message: 'Kindly fill the full form'})
      return
    }

    const flag = Object.keys(multiBenefitAutoApprovalPayload).length && Object.keys(multiBenefitAutoApprovalPayload).map((key) => multiBenefitAutoApprovalPayload[key]).every(({ is_approved }) => is_approved !== undefined)

    if (!flag) {
      notification.error({ message: 'Kindly fill the full form'})
      return
    }

    this.props.submitEvent({
      ...multiBenefitAutoApprovalPayload,
    })
  }


  render() {
    const { formData = {}, title, } = this.props
    const { selectedBenefit, multiBenefitAutoApprovalPayload } = this.state

    const { multi_benefit_form_data: multiBenefitFormData = {} } = formData

    const getValueFromPayload = (benefitKey, name, value) => {
      if (multiBenefitAutoApprovalPayload[benefitKey]) {
        return multiBenefitAutoApprovalPayload[benefitKey][name] || undefined
      }
      return value
    }


    return (
      <MultiBenefitAutoApprovalEventWrapper>
        <div className='modal-header'>
          {title}
        </div>
        {multiBenefitFormData && Object.keys(multiBenefitFormData).map((benefitKey) => {
          const {
            benefit_id: code = "",
            name: title = '',
            form_data: formData,
            is_auto_approved: isAutoApproved = false,
          } = multiBenefitFormData[benefitKey]
          const { remarks = '', amount = '', images = '' } = multiBenefitAutoApprovalPayload[benefitKey] || {}
          const {filePreview={}} = this.state
          this['formRef' + benefitKey] = React.createRef()

          let autoApprovedAmount = 0

          if (isAutoApproved) {
            formData.forEach((attr) => {
              const { name, value } = attr
              if (name === 'amount' && value) {
                autoApprovedAmount = value
              }
            })
          }

          return (
            <div>
              <Title isAutoApproved={isAutoApproved} onClick={() => this.selectOrDeselectBenefit(code)}>{title}</Title>
              {
                selectedBenefit.includes(code) ?
                  isAutoApproved ?
                    <div>
                      <div>The claim has been approved by JARVIS</div>
                      <InfoContainer><div>Amount:</div><div>{autoApprovedAmount}</div></InfoContainer>
                    </div>
                    :
                    multiBenefitAutoApprovalPayload.hasOwnProperty(benefitKey) &&
                      multiBenefitAutoApprovalPayload[benefitKey].is_approved !== undefined
                      ?
                      <div>
                        {remarks ? <InfoContainer><div>Remarks:</div> <div>{remarks}</div></InfoContainer> : null}
                       <InfoContainer>
                          <div>
                            Images:
                          </div>
                          {images ?
                          <div>
                            <img src={filePreview[benefitKey]} alt="auto_approval_image" style={{
                              width: 100,
                              height: 100,
                            }} />
                          </div>
                          : 'N/A'}
                        </InfoContainer>
                        {amount ? <InfoContainer>
                          <div> Amount: </div>
                          <div> {amount}</div>
                        </InfoContainer> : null}
                        <div>
                          <div>Status: {multiBenefitAutoApprovalPayload[benefitKey].is_approved === true ? 'Approved' : 'Rejected'}</div>
                          <ChangeStatus onClick={() => this.changeStatusClickHandler(benefitKey)}>Change status</ChangeStatus>
                        </div>
                      </div>
                      :
                      <div>
                        <Form ref={this['formRef' + benefitKey]} onFinish={(values) => this.handleFinish(values, benefitKey)}>
                          {formData.map(({ name, type, options, label, required, value }) =>
                            <FormItem name={name} label={label} key={name}
                              rules={[{ required: required, message: `Please input your ${label}!` }]}
                              initialValue={type === 'choices' && options?.length === 1 ? options[0][0] : getValueFromPayload(benefitKey, name, value)}
                            >
                              {this.renderAttribute(type, label, name, options, getValueFromPayload(benefitKey, name, value), benefitKey)}
                            </FormItem>
                          )}
                          <ButtonContainer>
                            <ApproveButton onClick={(e) => this.approveOrRejectClickHandler(e, true, benefitKey)}>
                              Approve
                            </ApproveButton>
                            <RejectButton onClick={(e) => this.approveOrRejectClickHandler(e, false, benefitKey)}>Reject</RejectButton>
                          </ButtonContainer>
                        </Form>
                      </div>
                  : null
              }
            </div>
          )
        })
        }
          <Row justify='end'>
              <Button
                className='cancel-button'
                onClick={this.props.closeModal}
              >
                Cancel
              </Button>
              <FormItem>
                <Button
                  htmlType='submit'
                  type='primary'
                  className='submit-button'
                  onClick={this.saveAutoApprovalFlow}
                >
                  Submit
              </Button>
              </FormItem>
            </Row>
      </MultiBenefitAutoApprovalEventWrapper >

    )
  }
}

export default connect(state => ({
  generateSignedUrlLoading: state.Loading.GENERATE_SIGNED_URL,
  generateSignedUrlError: state.Error.GENERATE_SIGNED_URL,
  generateSignedUrlStatus: state.Claim.signedUrlStatus,
  signedUrl: state.Claim.signedUrl
}), {
  resetLoadingRedux,
  resetErrorRedux,
  generateSignedUrl
})(MultiBenefitAutoApprovalEvent)
