import React, { Component } from 'react'
import { connect } from 'react-redux'
import { find, get, values } from 'lodash'
import moment from 'moment-timezone'
import { Row, Col, Button, Modal, notification, Tag, Checkbox } from 'antd'
import Viewer from './Viewer'
import PdfViewerModal from './PdfViewerModal'

import { FormStyle, RemarksDiv, StatusContainer } from './component.style'
import { Header } from '../../../../../components/StyledComponents'
import GenericForm from '../../../../../components/GenericForm'
import claimActions from '../../../../redux/claims/actions'
import loadingActions from '../../../../../redux/loading/actions'
import errorActions from '../../../../../redux/error/actions'
import PermissionChecker from '../../../../../components/PermissionChecker'
import { APP_COLORS } from '../../../../../constants/colors'
import ImageComponent from './imageComponent'
import FieldRenderer from './FieldRenderer'
import ComparePolicyModal from './ComparePolicyModal'
import { InformationOCRFormAUS } from '../Details/components/InformationOCRFormAUS'
import { Fragment } from 'react'

const allowShowOCRClaimInformation = ['ppagency-car-protection','ppagency-agency-motor-vehicle']
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions
const {
  saveForm,
  resetUploadData,
  resetUploadFailure,
  getChoicesData,
  getServiceCenterList,
  triggerClaimAttributeEvent,
  triggerClaimEvent,
  getClaimDetails,
  generateSignedUrl,
  verifyBankAccount,
} = claimActions
class Form extends Component {
  _fieldUpdaters = {}
  state = {
    showEventModal: false,
    modalEventFormData: {},
    attributeName: '',
    showDocument: false,
    imageUrl: '',
    formValues: {},
    submitAttempted: {},
    submittedForms: {},
    formCompletionStatus: {},
    bankVerificationStatus: {},
    showComparePolicyModal: false,
    comparePolicyFilter: null,
    comparePolicyFormName: null,
    pdfModalVisible: false,
    pdfFileUrl: '',
    viewerContext: { type: null, index: 0, items: [] },
    pendingUploads: {},
    failedUploads: {}
  }

  // Open media (image or PDF) in the appropriate viewer
  handleOpenMedia = (url, context = null, fileName = '', fileType = '') => {
    if (!url || typeof url !== 'string') return
    const lower = url.toLowerCase()
    const fileLower = (fileName || '').toLowerCase()
    const isPdf = fileType === 'application/pdf' || fileLower.includes('.pdf') || lower.includes('.pdf')
    if (isPdf) {
      this.setState({ pdfModalVisible: true, pdfFileUrl: url })
    } else {
      const viewerContext = (context && context.items)
        ? { type: context.type || null, index: context.index || 0, items: context.items }
        : { type: null, index: 0, items: [url] }
      this.setState({ showDocument: true, imageUrl: url, viewerContext })
    }
  }

  _viewerNavigate = (direction) => {
    const { viewerContext = {} } = this.state
    const { items = [], index = 0 } = viewerContext
    if (!Array.isArray(items) || items.length === 0) return
    let newIndex = index
    if (direction === 'prev') newIndex = Math.max(0, index - 1)
    if (direction === 'next') newIndex = Math.min(items.length - 1, index + 1)
    if (newIndex !== index) {
      const newContext = { ...viewerContext, index: newIndex }
      this.setState({ viewerContext: newContext, imageUrl: items[newIndex] })
    }
  }

  handleViewerPrev = () => this._viewerNavigate('prev')

  handleViewerNext = () => this._viewerNavigate('next')

  // Keyboard navigation for viewer (left/right arrows)
  _onViewerKeyDown = (e) => {
    if (!this.state.showDocument) return
    if (e.key === 'ArrowLeft') this._viewerNavigate('prev')
    if (e.key === 'ArrowRight') this._viewerNavigate('next')
  }

  componentDidUpdate(prevProps, prevState) {
    // attach/detach keydown listener when viewer opens/closes
    if (!prevState.showDocument && this.state.showDocument) {
      this._boundViewerKeyDown = this._onViewerKeyDown.bind(this)
      window.addEventListener('keydown', this._boundViewerKeyDown)
    } else if (prevState.showDocument && !this.state.showDocument) {
      if (this._boundViewerKeyDown) {
        window.removeEventListener('keydown', this._boundViewerKeyDown)
        this._boundViewerKeyDown = null
      }
    }
  }

  componentWillUnmount() {
    if (this._boundViewerKeyDown) {
      window.removeEventListener('keydown', this._boundViewerKeyDown)
      this._boundViewerKeyDown = null
    }
  }

  _activeUploads = {}
  _processedUploads = new Set()

  _clearUploadState = (bareFieldName, failedUploadId = null) => {
    if (!this.fieldRenderers) return
    Object.keys(this.fieldRenderers).forEach(fn => {
      this.fieldRenderers[fn].clearUploadFailure(bareFieldName, failedUploadId)
    })
  }

  _makeIdentifier = (formName, fieldName) => `${formName}:${fieldName}`

  handleMultiUpload = (fileList, fieldName, formName, updateFieldValue, isMultiple, currentValue) => {
    const identifier = this._makeIdentifier(formName, fieldName)
    const isUploadActive = !!this._activeUploads[identifier]
    const MAX_FILES = 50
    const acceptedTypes = ['image/jpeg', 'image/jpg', 'image/png', 'application/pdf']

    const currentPending = this.state.pendingUploads[identifier] || []
    const currentFailed = this.state.failedUploads[identifier] || []
    const currentFormValue = this.state[formName]?.[fieldName]
    const existingCount = (Array.isArray(currentFormValue) ? currentFormValue.length : currentFormValue ? 1 : 0)
      + currentPending.length + currentFailed.length

    const toQueue = []

    for (const f of fileList) {
      const uid = f.uid
      const dedupKey = `${identifier}-${uid}`
      const rawFile = f.originFileObj || f

      if (this._processedUploads.has(dedupKey)) continue
      if (existingCount + toQueue.length >= MAX_FILES) {
        const { message: antMessage } = require('antd')
        antMessage.warning(`Max ${MAX_FILES} files allowed`)
        break
      }

      const sizeMB = (rawFile.size || 0) / 1024 / 1024
      if (sizeMB < 0.01) {
        const { message: antMessage } = require('antd')
        antMessage.error(`${f.name}: terlalu kecil, min 10kb`)
        continue
      }
      if (sizeMB > 5) {
        const { message: antMessage } = require('antd')
        antMessage.error(`${f.name}: terlalu besar, max 5mb`)
        continue
      }
      if (!acceptedTypes.includes(rawFile.type)) {
        const { notification: antNotif } = require('antd')
        antNotif.error({ message: `${f.name}: hanya JPG, JPEG, PNG, PDF` })
        continue
      }

      const duplicate = currentPending.some(p => p.name === f.name)
        || currentFailed.some(p => p.name === f.name)
      if (duplicate) continue

      this._processedUploads.add(dedupKey)
      toQueue.push({ file: f, name: f.name, uid, preview: URL.createObjectURL(rawFile) })
    }

    if (toQueue.length === 0) return

    this.setState(prevState => ({
      pendingUploads: {
        ...prevState.pendingUploads,
        [identifier]: [...(prevState.pendingUploads[identifier] || []), ...toQueue]
      }
    }), () => {
      const pending = this.state.pendingUploads[identifier] || []
      if (!isUploadActive && pending.length > 0) {
        this._activeUploads[identifier] = true
        this.uploadSingleFile(pending[0].file, identifier, fieldName, formName, pending[0].preview)
      }
    })
  }

  uploadSingleFile = (file, identifier, fieldName, formName, preview = null) => {
    const uploadId = `${identifier}_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`
    const rawFile = file.originFileObj || file
    const formData = { name: rawFile.name, type: rawFile.type }

    // Stage context in FieldRenderer so updateSignedUrl can find it
    const fr = this.fieldRenderers[formName]
    if (fr) {
        const updaterKey = identifier // identifier is formName:fieldName
        const updateFieldValue = this._fieldUpdaters[updaterKey]
        const currentValue = this.state[formName]?.[fieldName]
        const isMultiple = true // For multi-upload path, always treat as multiple

        if (updateFieldValue) {
            fr.stageUploadContext(identifier, updateFieldValue, isMultiple, currentValue, file, uploadId, preview)
        }
    }

    this.props.generateSignedUrl({
      body: { formData },
      uploadedFile: rawFile,
      fieldName: identifier,
      uploadId
    })
  }

  retryUpload = (item, identifier) => {
    const parts = identifier.split(':')
    const formName = parts[0]
    const fieldName = parts.slice(1).join(':')

    this.setState(prevState => ({
      failedUploads: {
        ...prevState.failedUploads,
        [identifier]: (prevState.failedUploads[identifier] || []).filter(f => f.uid !== item.uid)
      },
      pendingUploads: {
        ...prevState.pendingUploads,
        [identifier]: [...(prevState.pendingUploads[identifier] || []), item]
      }
    }), () => {
      this.uploadSingleFile(item.file, identifier, fieldName, formName, item.preview)
    })
  }

  advanceQueue = (identifier) => {
    this.setState(prevState => {
      const queue = prevState.pendingUploads[identifier] || []
      const remaining = queue.slice(1)
      return {
        pendingUploads: {
          ...prevState.pendingUploads,
          [identifier]: remaining
        }
      }
    }, () => {
      const parts = identifier.split(':')
      const formName = parts[0]
      const fieldName = parts.slice(1).join(':')
      const next = (this.state.pendingUploads[identifier] || [])[0]
      if (next) {
        this.uploadSingleFile(next.file, identifier, fieldName, formName, next.preview)
      } else {
        this._activeUploads[identifier] = false
        this._processedUploads = new Set()
      }
    })
  }

  componentDidMount() {
    this.props.getServiceCenterList()
    this.props.resetLoadingRedux(['TRIGGER_CLAIM_ATTRIBUTE_EVENT', 'TRIGGER_CLAIM_EVENT', 'SAVE_FORM'])
    this.props.resetErrorRedux(['TRIGGER_CLAIM_ATTRIBUTE_EVENT', 'TRIGGER_CLAIM_EVENT', 'SAVE_FORM'])

    // Initialize form state with existing claim data
    this.initializeFormStateFromClaimDetails(this.props.claimDetails)
  }

  // Initialize or update form state with data from claim details
  initializeFormStateFromClaimDetails = (claimDetails) => {
    if (!claimDetails || !claimDetails.forms) {
      return
    }

    const newState = {}

    // Iterate through each form in claim details
    claimDetails.forms.forEach(form => {
      const formName = form.name
      const formState = {}

      // Iterate through attributes and populate existing values
      if (form.attributes) {
        form.attributes.forEach(attribute => {
          const { name, value, id } = attribute
          if (value !== null && value !== undefined) {
            // Workshop-selection: API gives label in value, ID in id field
            // Store as JSON string to match Select option format
            if (['sc_province', 'sc_city', 'sc_workshop'].includes(name) && id) {
              formState[name] = JSON.stringify({ id, name: value })
            } else {
              formState[name] = value
            }
          }
        })
      }

      // Only set state if there are values to populate
      if (Object.keys(formState).length > 0) {
        newState[formName] = formState
      }
    })

    if (Object.keys(newState).length > 0) {
      this.setState(newState)
    }
  }

  // Check if all forms are filled based on is_valid property
  checkIfAllFormsFilled = () => {
    const { claimDetails = {} } = this.props
    const { forms = [] } = claimDetails

    if (!forms.length) return false

    // Use the is_valid property from each form to determine completion
    const allFormsFilled = forms.every(form => {
      const { is_valid = false } = form
      return is_valid
    })

    return allFormsFilled
  }

  // Check if forms should be read-only based on completion and status
  shouldFormsBeReadOnly = () => {
    const { claimDetails = {} } = this.props
    const { status = {} } = claimDetails
    const statusCode = status.status_code

    // Forms are read-only if:
    // 1. All forms are filled AND
    // 2. Status is 'initiated' or 'document_pending'
    const allFormsFilled = this.checkIfAllFormsFilled()
    const statusRequiresReadOnly = ['initiated', 'document_pending'].includes(statusCode)

    const shouldBeReadOnly = allFormsFilled && statusRequiresReadOnly

    return shouldBeReadOnly
  }

  // Check if a specific form should be read-only
  shouldFormBeReadOnly = (formName) => {
    const { claimDetails = {} } = this.props
    const { status = {}, forms = [] } = claimDetails
    const statusCode = status.status_code

    // Find the specific form
    const currentForm = forms.find(form => form.name === formName)
    if (!currentForm) return false

    // Form is read-only if:
    // 1. The form is valid (is_valid: true) AND
    // 2. Status is 'initiated' or 'document_pending'
    const formIsValid = currentForm.is_valid
    const statusRequiresReadOnly = ['initiated', 'document_pending'].includes(statusCode)

    const shouldBeReadOnly = formIsValid && statusRequiresReadOnly

    return shouldBeReadOnly
  }

  // Reset form state when claim status changes (allows re-editing)
  resetFormStateOnStatusChange = (newStatus, oldStatus) => {
    // Reset form state if status changes to allow re-editing
    const statusesAllowingEdit = ['reprocess']

    if (statusesAllowingEdit.includes(newStatus) && newStatus !== oldStatus) {
      // Clear any form submission tracking since status allows re-editing
      this.setState({
        submittedForms: {},
        formCompletionStatus: {},
        bankVerificationStatus: {}
      })
    }
  }

  // Check if a form is a bank form
  isBankForm = (formName) => {
    return formName === 'bank-details'
  }

  // Check if bank verification is required and completed for a form
  isBankVerificationRequired = (formName) => {
    return this.isBankForm(formName)
  }

  // Check if bank verification is completed for a form
  isBankVerificationCompleted = (formName) => {
    const { bankVerificationData } = this.props
    const verificationStatus = this.state.bankVerificationStatus[formName]
    return verificationStatus === 'verified' && bankVerificationData?.is_valid
  }

  // Handle bank verification
  handleBankVerification = (formName) => {
    const formValues = this.state[formName]

    if (!formValues?.account_number || !formValues?.bank_name) {
      notification['error']({ message: 'Please fill in account number and bank name before verification' })
      return
    }

    // Set verification status to verifying
    this.setState(prevState => ({
      bankVerificationStatus: {
        ...prevState.bankVerificationStatus,
        [formName]: 'verifying'
      }
    }))

    // Call verification API
    this.props.verifyBankAccount({
      body: {
        account_number: formValues.account_number,
        bank_code: formValues.bank_name
      }
    })
  }

  componentWillReceiveProps(nextProps) {
    const { triggerClaimEventLoading, triggerClaimEventError, triggerClaimEventMessage,
      triggerClaimEventMainLoading, triggerClaimEventMainError, triggerClaimEventMainMessage,
      saveFormLoading, saveFormError, saveFormDataMessage, signedUrl, claimDetails,
      verifyBankAccountLoading, verifyBankAccountError, bankVerificationData, bankVerificationMessage,
      uploadFailedField
    } = nextProps

    // Handle upload failure — FIFO: move oldest pending → failed
    if (uploadFailedField && uploadFailedField !== this.props.uploadFailedField) {
      const identifier = uploadFailedField
      const bareFieldName = identifier.split(':').pop()
      const pending = this.state.pendingUploads[identifier] || []
      if (pending.length > 0) {
        const [failedItem, ...remaining] = pending
        this.setState(prevState => ({
          pendingUploads: {
            ...prevState.pendingUploads,
            [identifier]: remaining
          },
          failedUploads: {
            ...prevState.failedUploads,
            [identifier]: [...(prevState.failedUploads[identifier] || []), failedItem]
          }
        }), () => {
          this._clearUploadState(bareFieldName, this.props.uploadFailedUploadId)
          if (remaining.length > 0) {
            this.advanceQueue(identifier)
          } else {
            this._activeUploads[identifier] = false
          }
        })
      } else {
        let failedItem = null
        let failedId = null
        Object.keys(this.fieldRenderers || {}).forEach(fn => {
          const fr = this.fieldRenderers[fn]
          const ctx = fr.state.fieldUploadContexts?.[bareFieldName]
          if (ctx?.file) {
            failedItem = {
              file: ctx.file,
              name: ctx.name || bareFieldName,
              uid: ctx.fileUid || `${bareFieldName}-${Date.now()}`,
              preview: ctx.preview || null
            }
            failedId = `${fn}:${bareFieldName}`
          }
        })
        this._clearUploadState(bareFieldName, this.props.uploadFailedUploadId)
        this._activeUploads[identifier] = false
        if (failedItem && failedId) {
          this.setState(prev => ({
            failedUploads: {
              ...prev.failedUploads,
              [failedId]: [...(prev.failedUploads[failedId] || []), failedItem]
            }
          }))
        }
      }
      this.props.resetUploadFailure()
    }

    // Handle upload success — clear first pending and advance queue
    if (signedUrl !== this.props.signedUrl && signedUrl && signedUrl.url) {
      if (this.fieldRenderers) {
        Object.keys(this.fieldRenderers).forEach(formName => {
          this.fieldRenderers[formName].updateSignedUrl(signedUrl)
        })
      }
      // advance queue for the matching identifier
      const completedField = nextProps.uploadCompletedField || null
      if (completedField) {
        this.advanceQueue(completedField)
      } else {
        // fallback: find identifier with pending uploads and advance
        Object.keys(this.state.pendingUploads).forEach(identifier => {
          if ((this.state.pendingUploads[identifier] || []).length > 0) {
            this.advanceQueue(identifier)
          }
        })
      }
    }

    // Handle bank verification response
    if (verifyBankAccountLoading === false) {
      const bankFormName = 'bank-details'

      if (verifyBankAccountError === false && bankVerificationData?.is_valid) {
        // Verification successful
        notification['success']({ message: `Bank account verified successfully. Account holder: ${bankVerificationData.account_holder_name}` })
        this.setState(prevState => ({
          bankVerificationStatus: {
            ...prevState.bankVerificationStatus,
            [bankFormName]: 'verified'
          }
        }))
      } else {
        // Verification failed
        notification['error']({ message: bankVerificationMessage || 'Bank verification failed' })
        this.setState(prevState => ({
          bankVerificationStatus: {
            ...prevState.bankVerificationStatus,
            [bankFormName]: 'failed'
          }
        }))
      }

      this.props.resetLoadingRedux(['VERIFY_BANK_ACCOUNT'])
      this.props.resetErrorRedux(['VERIFY_BANK_ACCOUNT'])
    }

    // Handle signed URL updates — already handled above in success block
    // (kept for non-multi-upload fields that don't go through handleMultiUpload)
    if (signedUrl !== this.props.signedUrl && !(signedUrl && signedUrl.url) && this.fieldRenderers) {
      Object.keys(this.fieldRenderers).forEach(formName => {
        this.fieldRenderers[formName].updateSignedUrl(signedUrl)
      })
    }

    // Reinitialize form state when claim details are updated (e.g., after successful save)
    if (claimDetails !== this.props.claimDetails && claimDetails) {
      this.initializeFormStateFromClaimDetails(claimDetails)

      // Check for status changes and reset form state if needed
      const oldStatus = this.props.claimDetails?.status?.status_code
      const newStatus = claimDetails?.status?.status_code
      if (oldStatus !== newStatus) {
        this.resetFormStateOnStatusChange(newStatus, oldStatus)
      }
    }

    if (triggerClaimEventLoading === false) {
      if (triggerClaimEventError === false) {
        this.setState({ showEventModal: false })
        this.props.resetUploadData()
      }
      notification[triggerClaimEventError ? 'error' : 'success']({ message: triggerClaimEventMessage })
      this.props.resetLoadingRedux(['TRIGGER_CLAIM_ATTRIBUTE_EVENT'])
      this.props.resetErrorRedux(['TRIGGER_CLAIM_ATTRIBUTE_EVENT'])
    }

    if (saveFormLoading === false) {
      notification[saveFormError ? 'error' : 'success']({ message: saveFormDataMessage })

      // If form was saved successfully, refetch claim details to get updated status
      if (!saveFormError) {
        const { claimDetails = {} } = this.props
        const { claim_id: claimID } = claimDetails

        // Add delay to allow backend to finish updating before refetching
        setTimeout(() => {
          this.props.getClaimDetails({
            query: {
              claim_id: claimID
            }
          })
        }, 2000) // 2 second delay to ensure backend has processed the status update

        // Clear any pending trigger flags and reset submit attempted state
        this.setState({
          triggerEventAfterSave: null,
          submitAttempted: {} // Reset all submit attempts after successful save
        })
      }

      this.props.resetLoadingRedux(['SAVE_FORM'])
      this.props.resetErrorRedux(['SAVE_FORM'])
    }

    // Handle triggerClaimEvent response (triggered after form save)
    if (triggerClaimEventMainLoading === false) {
      notification[triggerClaimEventMainError ? 'error' : 'success']({
        message: triggerClaimEventMainMessage || 'Claim event triggered successfully'
      })
      this.props.resetLoadingRedux(['TRIGGER_CLAIM_EVENT'])
      this.props.resetErrorRedux(['TRIGGER_CLAIM_EVENT'])
    }
  }

  handleEventSubmit = (values) => {
    const { claimDetails = {} } = this.props
    const { modalEventData, attributeName, formName } = this.state
    const { claim_id: claimID, status } = claimDetails
    const { code, display_name } = modalEventData

    if(values?.remarks === 'diverifikasi' && display_name === 'Reject') {
      notification['error']({ message: 'Remarks is required' })
      return
    }

    if(display_name === 'Accept') {
      values.remarks = 'diverifikasi'
    }

    this.props.triggerClaimAttributeEvent({
      body: {
        data: {
          ...values,
          images: get(values, 'images', null),
          form_name: formName,
          name: attributeName,
        },
        event_code: code,
        status: get(status, 'status_code'),
        claim_id: claimID
      }
    })

  }

  rendertriggerEvent = (event, name, formName) => {
    const { display_name: displayName, code } = event

    if (["document_approved_by_pp", "document_rejected_by_pp"].includes(code)) {
      return
    }

    return <Button
      key={displayName}
      type='primary'
      className={`action-button ${displayName === 'Reject' ? 'reject-button' : 'accept-button'}`}
      onClick={() => {
        this.setState({ showEventModal: true, modalEventData: event, attributeName: name, formName })
      }}
    >
      {displayName}
    </Button>
  }

  handleSaveForm = (formName, eventToTriggerAfterSave = null) => {
    // Mark that submit has been attempted for this form
    this.setState(prevState => ({
      submitAttempted: {
        ...prevState.submitAttempted,
        [formName]: true
      }
    }))

    const { claimDetails = {} } = this.props
    const { claim_id: claimID, userid } = claimDetails
    let saveFormValues = this.state[formName]

    // Client-side required field validation
    const formDef = (this.props.claimDetails.forms || []).find(f => f.name === formName)
    if (formDef && formDef.attributes) {
      const missingRequired = formDef.attributes.filter(attr => attr.required && !this.state[formName]?.[attr.name])
      if (missingRequired.length > 0) {
        const labels = missingRequired.map(attr => attr.label).join(', ')
        notification['error']({ message: `Please fill required fields: ${labels}` })
        return
      }
    }

    // Transform workshop-selection object values to id + display_name keys
    if (formName === 'workshop-selection') {
      const transformed = {}
      const fields = ['sc_province', 'sc_city', 'sc_workshop']
      fields.forEach(key => {
        const val = saveFormValues?.[key]
        if (!val) return
        const obj = JSON.parse(val)
        transformed[key] = obj?.id ?? val
        transformed[`${key}_display_value`] = obj?.name ?? val
      })
      saveFormValues = transformed
    }

    if (values(saveFormValues).length > 0) {
      // If event should be triggered after save, store it in state
      if (eventToTriggerAfterSave) {
        this.setState({
          triggerEventAfterSave: eventToTriggerAfterSave
        })
      }

      const payload = {
        body: {
          claim_id: claimID,
          form_slug: formName,
          user_id: userid,
          ...saveFormValues
        }
      }

      this.props.saveForm(payload)
    } else {
      notification['error']({ message: 'Invalid Form Values' })
    }
  }

  // Method to save form and trigger specific claim event
  handleSaveFormAndTriggerEvent = (formName, eventCode, eventData = {}) => {
    this.handleSaveForm(formName, { eventCode, eventData })
  }

  handleChoicesExternalChange = (value, apiPath) => {
    if (value.length > 2) {
      this.props.getChoicesData({
        query: {
          api_endpoint: apiPath,
          search_key: value
        }
      })
    }
  }

  getStatusTextAndColor = (status) => {
    if (status === "validated_by_pp") {
      return ["Approved by Pasarpolis", "#87d068"]
    } else {
      return ["Rejected by Pasarpolis", "#f50"]
    }
  }

  renderEditableField = (type, name, formName, label, options = [], attributeData = {}, isRequired = false, submitAttempted = false, originalValue = null) => {
    const { choicesData = [], choicesDataLoading, bengkelOptions, bengkelLoading } = this.props
    // Use form state value if available, otherwise fall back to original attribute value
    const currentValue = this.state[formName]?.[name] !== undefined ? this.state[formName]?.[name] : originalValue

    // Override options for workshop-selection form with live API data
    if (formName === 'workshop-selection' && bengkelOptions) {
      if (name === 'sc_province') { options = bengkelOptions.province; attributeData = { ...attributeData, loading: bengkelLoading?.province } }
      if (name === 'sc_city') { options = bengkelOptions.city; attributeData = { ...attributeData, loading: bengkelLoading?.city } }
      if (name === 'sc_workshop') { options = bengkelOptions.workshop; attributeData = { ...attributeData, loading: bengkelLoading?.workshop } }
    }

    // Check if this specific form should be read-only based on its validity and status
    const shouldBeReadOnly = this.shouldFormBeReadOnly(formName)

    // If form should be read-only, show read-only value instead of editable field
    if (shouldBeReadOnly) {
      return this.renderValue(type, currentValue, options, name, attributeData)
    }

    const updateFieldValue = (value) => {
      // Prevent updates if this form should be read-only
      const shouldBeReadOnly = this.shouldFormBeReadOnly(formName)
      if (shouldBeReadOnly) {
        return
      }

      const formNameState = this.state[formName] || {}
      formNameState[name] = value

      // Clear dependent fields for workshop-selection cascade
      if (formName === 'workshop-selection') {
        if (name === 'sc_province') {
          delete formNameState.sc_city
          delete formNameState.sc_workshop
        }
        if (name === 'sc_city') {
          delete formNameState.sc_workshop
        }
      }

      this.setState({ [formName]: formNameState })

      // Trigger cascading fetch for workshop-selection fields
      if (formName === 'workshop-selection' && this.props.onBengkelFieldChange) {
        let rawId = value
        try { rawId = JSON.parse(value).id } catch {}
        this.props.onBengkelFieldChange(name, rawId)
      }
    }

    // Register the updater so uploadSingleFile can find it
    const updaterKey = `${formName}:${name}`
    this._fieldUpdaters[updaterKey] = updateFieldValue

    const { generateSignedUrlLoading, generateSignedUrl, signedUrl } = this.props

    // Create form-specific fieldRenderer instances to prevent cross-form interference
    if (!this.fieldRenderers) {
      this.fieldRenderers = {}
    }

    if (!this.fieldRenderers[formName]) {
      this.fieldRenderers[formName] = new FieldRenderer({
        choicesData,
        choicesDataLoading,
        handleChoicesExternalChange: this.handleChoicesExternalChange,
        onImagePreview: (imageUrl, ...args) => this.handleOpenMedia(imageUrl, null, ...args),
        generateSignedUrlLoading,
        generateSignedUrl,
        signedUrl,
        pendingUploads: this.state.pendingUploads,
        failedUploads: this.state.failedUploads,
        onMultiUpload: (fileList, fieldName, updateFieldValue, isMultiple, currentValue) => this.handleMultiUpload(fileList, fieldName, formName, updateFieldValue, isMultiple, currentValue),
        retryUpload: (item, identifier) => this.retryUpload(item, identifier),
        formName
      })
    } else {
      this.fieldRenderers[formName].props = {
        choicesData,
        choicesDataLoading,
        handleChoicesExternalChange: this.handleChoicesExternalChange,
        onImagePreview: (imageUrl, ...args) => this.handleOpenMedia(imageUrl, null, ...args),
        generateSignedUrlLoading,
        generateSignedUrl,
        signedUrl,
        pendingUploads: this.state.pendingUploads,
        failedUploads: this.state.failedUploads,
        onMultiUpload: (fileList, fieldName, updateFieldValue, isMultiple, currentValue) => this.handleMultiUpload(fileList, fieldName, formName, updateFieldValue, isMultiple, currentValue),
        retryUpload: (item, identifier) => this.retryUpload(item, identifier),
        formName
      }
    }

    const fieldRenderer = this.fieldRenderers[formName]

    return fieldRenderer.render(type, name, currentValue, updateFieldValue, label, options, attributeData, isRequired, submitAttempted)
  }

  renderValue = (type, value, options, name, attributeData = {}, mediaContext) => {
    const { serviceCenterList = [] } = this.props
    if (!value && type !== "checkbox") {
      return '-'
    }
    if (['sc_province', 'sc_city', 'sc_workshop'].includes(name)) {
      try { return JSON.parse(value).name } catch { return value }
    }
    if (name === 'sc_postal_code') return value
    if (name === 'claim_amount') return Intl.NumberFormat('en-US').format(value)

    if (name === 'service_center') {
      return decodeURI((serviceCenterList.find(({ code }) => value === code)?.name || value))
    }

    if (name === 'servicecenter_branch') {
      const { branch_info: branchInfo = {} } = attributeData
      const { branch_name: branchName = '', address, is_active: isActive } = branchInfo
      return (
        <div>
          <div>{`${branchName} -  ${address}`}</div>
          <div>Branch status:
            {
              isActive
                ? <StatusContainer isActive={isActive}> Active</StatusContainer>
                : <StatusContainer isActive={isActive}> Inactive</StatusContainer>
            }
          </div>
        </div>)

    }

    switch (type) {
      case 'boolean':
        return value === 'true'
          ? 'Yes'
          : 'No'
      case 'date':
        return value && moment(value).tz('Asia/Jakarta').format('DD-MM-YYYY')
      case 'sketch':
        if (Array.isArray(value)) {
          return <div className='image-container'>{value.map((val, idx) => <div key={idx}><ImageComponent value={val} width='auto' height={400} style={{ cursor: 'pointer' }} onClickImage={(url) => this.handleOpenMedia(url || val, { index: idx, items: value })} /></div>)}</div>
        }
        return <ImageComponent value={value} width='auto' height={400} style={{ cursor: 'pointer' }} onClickImage={(url) => this.handleOpenMedia(url || value, mediaContext)} />
      case 'image':
        if (Array.isArray(value)) {
          return <div className='image-container'>{value.map((val, idx) => <div key={idx}><ImageComponent value={val} onClickImage={(url) => this.handleOpenMedia(url || val, { index: idx, items: value })} /></div>)}</div>
        }
        return <ImageComponent value={value} onClickImage={(url) => this.handleOpenMedia(url || value, mediaContext)} />
      case 'choices_external':
        try {
          const data = JSON.parse(value)
          return `${get(data, 'name')} (${get(data, 'code')})`
        } catch (e) {
          return value
        }
      case 'choices':
        const resultObj = find(options, function (obj) {
          return obj[0] === value;
        })
        return resultObj && resultObj[1]
      case 'time':
        return moment(value, 'hh:mm').tz('Asia/Jakarta').format('h:mm A')

      case 'checkbox':
        return (<Checkbox
          checked={value || false}
        />)
      case 'disclaimer' :
        return value === true || value === 'true'
          ? 'Agree'
          : 'Disagree'
      default:
        return value
    }
  }

  renderAcceptRejectButtons = (events, name, formName) => {
    return (
      <div>
        <div
          style={{
            display: 'flex',
            flexWrap: 'wrap',
            flexDirection: 'row-reverse'
          }}
        >
          {
            events.map(event => this.rendertriggerEvent(event, name, formName))
          }
        </div>
      </div>
    )
  }

  renderAttributes = ({
    type,
    value,
    status,
    events = [],
    label,
    name,
    is_internal: isInternal,
    options,
    is_editable: isEditable,
    required = false,
    is_required = false,
    ...attributeData
  }, formName, formTitle) => {
    const textAndColour = this.getStatusTextAndColor(status)
    const isRequired = required || is_required || false
    const showComparePolicy = formTitle === 'Formulir Klaim' && (name === 'cardamages_front_back' || name === 'car_accident')
    const currentForm = (this.props.claimDetails?.forms || []).find(f => f.name === formName)
    const formIsValid = currentForm?.is_valid
    return <Fragment key={label}>
      <Row className='attribute-row' key={label}>
        <Col span={8} className='label'>
          {label}
          {isRequired && <span className='required-asterisk'> *</span>}
          <div>{["validated_by_pp", "invalidated_by_pp"].includes(status) && <Tag color={textAndColour[1]}>{textAndColour[0]}</Tag>}</div>
        </Col>
        {
          isEditable
            ?
            <Col span={12}>{this.renderEditableField(type, name, formName, label, options, attributeData, isRequired, this.state.submitAttempted[formName], value)}</Col>
            :
            typeof value === 'object' && value !== null
              ?
              <Col span={12} className='image-container'>
                {
                  value &&
                  value.map((val, idx) => <div key={idx}>{this.renderValue(type, val, options, name, attributeData, { index: idx, items: value })}</div>)
                }
              </Col>
              :
              <Col span={12}>{this.renderValue(type, value, options, name, attributeData)}</Col>
        }
        <PermissionChecker requiredPermission='verify_claim_documents'>
          <Col span={4}>
            <div>
                {showComparePolicy && (
                  <div style={{ marginBottom: '16px' }}>
                    <Button
                      style={
                        {
                          backgroundColor: 'rgb(89, 118, 192)',
                          color: '#FFF'
                        }
                      }
                      onClick={() => this.setState({ showComparePolicyModal: true, comparePolicyFilter: name, comparePolicyFormName: formName })}>
                      Compare With Policy Data
                    </Button>
                  </div>
                )}
              </div>
          {
            ["validated_by_pp", "invalidated_by_pp", "pending", "temporary"].includes(status) &&
            <>
              {this.renderAcceptRejectButtons(events, name, formName)}
            </>
          }
          </Col>
          {
            (status === 'valid' || status === 'invalid') &&
            <Col span={4}>
              <RemarksDiv color={status === 'valid' ? APP_COLORS.primary : APP_COLORS.error}>
                {status}
              </RemarksDiv>
            </Col>
          }
        </PermissionChecker>
      </Row>
      {allowShowOCRClaimInformation.some(i=>i=== this.props?.claimDetails?.display_name) && formIsValid && <InformationOCRFormAUS claimID={this.props.claimID} attributeName={name} formTitle={formTitle} policy={this.props?.claimDetails?.object_insured_images} />}

    </Fragment>

  }

  renderForm = (form = {}) => {
  const { triggerClaimEventLoading, saveFormLoading, claimDetails = {} } = this.props
  const { showEventModal, modalEventData, attributeName, showComparePolicyModal } = this.state
    const { title, attributes, name: formName, title: formTitle} = form
    const { status = {} } = claimDetails
    const statusCode = status.status_code
    // Only show submit button if status is 'initiated' or 'reprocess' AND form is not already valid
    const shouldShowSubmitButton = ['initiated', 'reprocess', 'document_pending'].includes(statusCode)
    const shouldBeReadOnly = this.shouldFormBeReadOnly(formName)
    return (
      <FormStyle key={form.name}>
        <Modal
          visible={showEventModal}
          footer={null}
          closable={false}
        >
          <GenericForm
            formData={get(modalEventData, 'form_data')}
            title={get(modalEventData, 'display_name')}
            closeModal={() => this.setState({ showEventModal: false })}
            handleFinish={values => this.handleEventSubmit(values)}
            visible={showEventModal}
            loading={triggerClaimEventLoading}
            attributeName={attributeName}
          />
        </Modal>
        <ComparePolicyModal
          visible={showComparePolicyModal}
          onClose={() => this.setState({ showComparePolicyModal: false, comparePolicyFilter: null, comparePolicyFormName: null })}
          claimDetails={claimDetails}
          filterKey={this.state.comparePolicyFilter}
          formName={this.state.comparePolicyFormName}
          handleOpenMedia={this.handleOpenMedia}
        />
        <Header content={title} />

        {/* Bank verification status indicator */}
        {this.isBankVerificationRequired(formName) && (
          <Row style={{ marginBottom: 16 }}>
            <Col span={24}>
              {this.state.bankVerificationStatus[formName] === 'verified' && this.props.bankVerificationData?.is_valid && (
                <div style={{
                  padding: '8px 12px',
                  backgroundColor: '#f6ffed',
                  border: '1px solid #b7eb8f',
                  borderRadius: '4px',
                  color: '#52c41a'
                }}>
                  ✓ Bank account verified successfully. Account holder: <strong>{this.props.bankVerificationData.account_holder_name}</strong>
                </div>
              )}
              {this.state.bankVerificationStatus[formName] === 'failed' && (
                <div style={{
                  padding: '8px 12px',
                  backgroundColor: '#fff2f0',
                  border: '1px solid #ffccc7',
                  borderRadius: '4px',
                  color: '#ff4d4f'
                }}>
                  ✗ Bank verification failed. Please check your account details and try again.
                </div>
              )}
              {this.state.bankVerificationStatus[formName] === 'verifying' && (
                <div style={{
                  padding: '8px 12px',
                  backgroundColor: '#e6f7ff',
                  border: '1px solid #91d5ff',
                  borderRadius: '4px',
                  color: '#1890ff'
                }}>
                  🔄 Verifying bank account details...
                </div>
              )}
              {!this.state.bankVerificationStatus[formName] && (
                <div style={{
                  padding: '8px 12px',
                  backgroundColor: '#fffbe6',
                  border: '1px solid #ffe58f',
                  borderRadius: '4px',
                  color: '#faad14'
                }}>
                  ⚠️ Bank account verification required before submitting this form.
                </div>
              )}
            </Col>
          </Row>
        )}

        <Row className='header-row'>
          <Col span={8}>Label</Col>
          <Col span={12}>Value</Col>
          <Col span={4}>Action</Col>
        </Row>
        <div>
          {
            attributes.map(attribute =>
              this.renderAttributes(attribute, get(form, 'name'), formTitle)
            )
          }
        </div>
        {shouldShowSubmitButton && !shouldBeReadOnly && (
          <Row justify='end' className='submit-row'>
            {this.isBankVerificationRequired(formName) && !this.isBankVerificationCompleted(formName) ? (
              <Button
                type='default'
                loading={!!this.props.verifyBankAccountLoading}
                onClick={() => this.handleBankVerification(formName)}
                style={{ marginRight: 8 }}
              >
                {this.state.bankVerificationStatus[formName] === 'failed' ? 'Retry Verification' : 'Verify Bank Account'}
              </Button>
            ) : null}

            <Button
              type='primary'
              loading={!!saveFormLoading || !!this.props.getClaimDetailsLoading}
              disabled={this.isBankVerificationRequired(formName) && !this.isBankVerificationCompleted(formName)}
              onClick={() => {
                this.handleSaveForm(formName)
              }}
            >
              Submit
            </Button>
          </Row>
        )}
      </FormStyle>
    )
  }

  render() {
    const { claimForms = [] } = this.props
    const { showDocument, imageUrl, viewerContext, pdfModalVisible, pdfFileUrl } = this.state

    return (
      <>
        <Viewer
          visible={showDocument}
          imageUrl={imageUrl}
          items={viewerContext.items}
          index={viewerContext.index}
          onPrev={this.handleViewerPrev}
          onNext={this.handleViewerNext}
          onClose={() => this.setState({
            showDocument: false,
            imageUrl: '',
            viewerContext: { type: null, index: 0, items: [] }
          })}
        />
        <PdfViewerModal
          visible={pdfModalVisible}
          onClose={() => this.setState({ pdfModalVisible: false, pdfFileUrl: '' })}
          fileUrl={pdfFileUrl}
        />
        {claimForms.map(form => this.renderForm(form))}
      </>
    )
  }
}

export default connect(state => ({
  claimDetails: state.Claim.claimDetails,
  serviceCenterList: state.Claim.serviceCenterList,

  triggerClaimEventMessage: state.Claim.triggerClaimAttributeEventMessage,
  triggerClaimEventLoading: state.Loading.TRIGGER_CLAIM_ATTRIBUTE_EVENT,
  triggerClaimEventError: state.Error.TRIGGER_CLAIM_ATTRIBUTE_EVENT,

  triggerClaimEventMainMessage: state.Claim.triggerClaimEventMessage,
  triggerClaimEventMainLoading: state.Loading.TRIGGER_CLAIM_EVENT,
  triggerClaimEventMainError: state.Error.TRIGGER_CLAIM_EVENT,

  saveFormLoading: state.Loading.SAVE_FORM,
  saveFormError: state.Error.SAVE_FORM,
  saveFormDataMessage: state.Claim.saveFormDataMessage,

  choicesData: state.Claim.choicesData,
  choicesDataLoading: state.Loading.GET_CHOICES_DATA,

  generateSignedUrlLoading: state.Loading.GENERATE_SIGNED_URL,
  generateSignedUrlError: state.Error.GENERATE_SIGNED_URL,
  generateSignedUrlStatus: state.Claim.signedUrlStatus,
  signedUrl: state.Claim.signedUrl,

  uploadFailedField: state.Claim.uploadFailedField,
  uploadFailedUploadId: state.Claim.uploadFailedUploadId,
  uploadCompletedField: state.Claim.uploadCompletedField,

  verifyBankAccountLoading: state.Loading.VERIFY_BANK_ACCOUNT,
  verifyBankAccountError: state.Error.VERIFY_BANK_ACCOUNT,
  bankVerificationData: state.Claim.bankVerificationData,
  bankVerificationMessage: state.Claim.bankVerificationMessage,

  getClaimDetailsLoading: state.Loading.GET_CLAIM_DETAIL
}), {
  getServiceCenterList,
  triggerClaimAttributeEvent,
  triggerClaimEvent,
  getClaimDetails,
  saveForm,
  resetUploadData,
  resetUploadFailure,
  getChoicesData,
  resetLoadingRedux,
  resetErrorRedux,
  generateSignedUrl,
  verifyBankAccount
})(Form)
