import React, { useEffect, useRef, useState } from 'react'
import html2canvas from 'html2canvas'
import { Button, message } from 'antd'
import { ButtonContainer, CarContainer, CarImage, Container, Marker, SketchImage } from './CarSketch.style'

const CarSketch = ({ value, onChange, generateSignedUrl, signedUrl }) => {
  const imageRef = useRef(null)
  const [selectedParts, setSelectedParts] = useState([])
  const [svgContent, setSvgContent] = useState('')
  const [error, setError] = useState(null)
  const [isSaving, setIsSaving] = useState(false)
  const [isUploading, setIsUploading] = useState(false)
  const [isSketchSaved, setIsSketchSaved] = useState(false)
  const [savedPreview, setSavedPreview] = useState(null)
  const [pendingUpload, setPendingUpload] = useState(false)
  const [myUploadTimestamp, setMyUploadTimestamp] = useState(null)

  useEffect(() => {
    fetch('https://pp-img-prod.s3.ap-southeast-3.amazonaws.com/tap-auto/Car+Frame.svg')
      .then(res => res.text())
      .then(setSvgContent)
      .catch(err => console.error('Failed to load SVG', err))
  }, [])

  useEffect(() => {
    if (signedUrl && pendingUpload && myUploadTimestamp) {
      const url = signedUrl?.url
      const timeDiff = Date.now() - myUploadTimestamp
      if (url && timeDiff < 15000 && url.includes('car-sketch')) {
        if (onChange) {
          onChange(url)
        }
        setPendingUpload(false)
        setMyUploadTimestamp(null)
        setIsSaving(false)
        setIsUploading(false)
      }
    }

    const timeoutId = setTimeout(() => {
      if (pendingUpload && myUploadTimestamp && Date.now() - myUploadTimestamp >= 15000) {
        setPendingUpload(false)
        setMyUploadTimestamp(null)
        setIsSaving(false)
        setIsUploading(false)
      }
    }, 15100)

    return () => clearTimeout(timeoutId)
  }, [signedUrl, pendingUpload, onChange, myUploadTimestamp])

  useEffect(() => {
    if (value) {
      setSelectedParts([])
      setIsSketchSaved(true)
      if (!savedPreview) {
        setSavedPreview(value)
      }
    } else {
      setIsSketchSaved(false)
      setSavedPreview(null)
    }
  }, [value])

  const toggleMarker = (event) => {
    if (!imageRef.current || isSketchSaved) return

    const rect = imageRef.current.getBoundingClientRect()
    const offsetX = ((event.clientX - rect.left) / rect.width) * 100
    const offsetY = ((event.clientY - rect.top) / rect.height) * 100

    const newMarker = {
      id: `${offsetX}-${offsetY}`,
      top: `${offsetY}%`,
      left: `${offsetX}%`
    }

    setSelectedParts(prev =>
      prev.some(p => p.id === newMarker.id)
        ? prev.filter(p => p.id !== newMarker.id)
        : [...prev, newMarker]
    )
  }

  const clearAllMarkers = () => setSelectedParts([])

  const handleSaveSketch = async () => {
    if (!imageRef.current || selectedParts.length === 0) {
      setError(selectedParts.length === 0 ? 'Please select at least one part.' : null)
      return
    }

    setIsSaving(true)
    setError(null)

    try {
      const canvas = await html2canvas(imageRef.current)
      const base64 = canvas.toDataURL('image/png')
      setSavedPreview(base64)
      setIsSketchSaved(true)
      setSelectedParts([])

      canvas.toBlob(async (blob) => {
        if (!blob) {
          setIsSaving(false)
          return
        }

        const sketchFile = new File([blob], 'car-sketch.png', { type: 'image/png' })
        const formData = { name: sketchFile.name, type: sketchFile.type }

        setIsUploading(true)
        const uploadTimestamp = Date.now()
        setMyUploadTimestamp(uploadTimestamp)
        setPendingUpload(true)

        if (generateSignedUrl) {
          generateSignedUrl({ body: { formData }, uploadedFile: sketchFile, fieldName: 'sketch' })
        }
      }, 'image/png')
    } catch (error) {
      setIsSaving(false)
      setIsUploading(false)
      message.error('Failed to save sketch')
    }
  }

  const handleReEdit = () => {
    setIsSketchSaved(false)
    setSelectedParts([])
    setSavedPreview(null)
    if (onChange) {
      onChange(null)
    }
  }

  return (
    <Container>
      {isSketchSaved ? (
        <div style={{ textAlign: 'center' }}>
          <SketchImage src={savedPreview} alt="Car sketch" />
          <div style={{ marginTop: 12 }}>
            <Button onClick={handleReEdit} type="primary">Re-edit</Button>
          </div>
        </div>
      ) : (
        <>
          <CarContainer onClick={toggleMarker} ref={imageRef}>
            <CarImage dangerouslySetInnerHTML={{ __html: svgContent }} />
            {selectedParts.map(({ id, top, left }) => (
              <Marker key={id} style={{ top, left }}>
                X
              </Marker>
            ))}
          </CarContainer>
          <ButtonContainer>
            <Button onClick={clearAllMarkers} danger>
              Clear Marker
            </Button>
            <Button
              onClick={handleSaveSketch}
              type="primary"
              loading={isSaving || isUploading}
              disabled={isSaving || isUploading}
            >
              Save Sketch
            </Button>
          </ButtonContainer>
          {error && <div style={{ color: 'red', marginTop: 8 }}>{error}</div>}
        </>
      )}
    </Container>
  )
}

export default CarSketch
