import { useQuery } from "@tanstack/react-query"
import claimEndpoints from "../endpoint/claim"
import authGet from "../methods/authGet"

export const GET_PROVINCE_LIST = 'GET_PROVINCE_LIST'
export const GET_CITY_LIST = 'GET_CITY_LIST'
export const GET_WORKSHOP_LIST = 'GET_WORKSHOP_LIST'

export const useGetProvinceList = () => {
  return useQuery({
    queryKey: [GET_PROVINCE_LIST],
    queryFn: () => authGet({url: claimEndpoints.bengkelnetProvinceList}),
    select: (data) => data?.data?.data
  })
}

export const useGetCityList = (provinceId) => {
  return useQuery({
    queryKey: [GET_CITY_LIST, provinceId],
    queryFn: () => authGet({url: claimEndpoints.bengkelnetCityList, query: { province_id: provinceId }}),
    enabled: !!provinceId,
    select: (data) => data?.data?.data
  })
}

export const useGetWorkshopList = (query) => {
  const { provinceId, cityId, claimId } = query || {}
  return useQuery({
    queryKey: [GET_WORKSHOP_LIST, query],
    queryFn: () => authGet({url: claimEndpoints.bengkelnetWorkshopList, query: {
      province_id: provinceId,
      city_id: cityId,
      claim_id: claimId,
    }}),
    enabled: !!provinceId && !!cityId && !!claimId,
    select: (data) => data?.data?.data
  })
}
