import React, { useState, useEffect, useMemo } from 'react'
import { Modal, Button } from 'antd'
import { ComparePolicyImageContainer, ComparePolicyImageItem, ComparePolicyImageTitle, ComparePolicyModalContainer, ComparePolicyModalItem } from './component.style'
import ImageComponent from './imageComponent'
import Viewer from './Viewer'
import PdfViewerModal from './PdfViewerModal'
import { get } from 'lodash'
import { getAttributesByName, getFormByName } from '../../../../../helpers/utility'

const ComparePolicyModal = ({ visible, onClose, claimDetails, filterKey, formName }) => {
  const formData = getFormByName(claimDetails, formName)
  const objectInsuredImage = get(claimDetails, 'object_insured_images.images', {})
  // Prepare object insured items array from known positions
  const objectPositions = useMemo(() => ['front', 'back', 'left', 'right', 'dashboard'], [])
  const objectItems = useMemo(() => objectPositions.map(pos => objectInsuredImage?.[pos]).filter(Boolean), [objectInsuredImage, objectPositions])

  // State
  // viewerContext holds which gallery opened the viewer and the items + current index
  const [viewerContext, setViewerContext] = useState({ type: null, index: 0, items: [] })
  const [viewerVisible, setViewerVisible] = useState(false)
  const [viewerImageUrl, setViewerImageUrl] = useState('')
  const [pdfVisible, setPdfVisible] = useState(false)
  const [pdfUrl, setPdfUrl] = useState('')

  // Effects
  // keyboard navigation while viewer is open
  useEffect(() => {
    if (!viewerVisible) return undefined

    const onKeyDown = (e) => {
      if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
        const { items = [], index = 0 } = viewerContext || {}
        if (!Array.isArray(items) || items.length === 0) return
        let newIndex = index
        if (e.key === 'ArrowLeft') newIndex = Math.max(0, index - 1)
        if (e.key === 'ArrowRight') newIndex = Math.min(items.length - 1, index + 1)
        if (newIndex !== index) {
          setViewerContext(prev => ({ ...prev, index: newIndex }))
          setViewerImageUrl(items[newIndex])
        }
      }
    }

    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [viewerVisible, viewerContext])

  // Event handlers
  const handleOpenMedia = (url, context = null) => {
    if (!url || typeof url !== 'string') return
    const lower = url.toLowerCase()
    if (lower.includes('.pdf')) {
      setPdfUrl(url)
      setPdfVisible(true)
      // clear viewer context when opening PDF
      setViewerContext({ type: null, index: 0, items: [] })
    } else {
      setViewerImageUrl(url)
      setViewerVisible(true)
      if (context && context.items) {
        setViewerContext({ type: context.type || null, index: context.index || 0, items: context.items })
      } else {
        setViewerContext({ type: null, index: 0, items: [url] })
      }
    }
  }

  // gallery controls for prev/next
  const handlePrev = () => {
    const { items = [], index = 0 } = viewerContext || {}
    if (!items || items.length === 0) return
    const newIndex = Math.max(0, index - 1)
    setViewerContext(prev => ({ ...prev, index: newIndex }))
    setViewerImageUrl(items[newIndex])
  }

  const handleNext = () => {
    const { items = [], index = 0 } = viewerContext || {}
    if (!items || items.length === 0) return
    const newIndex = Math.min(items.length - 1, index + 1)
    setViewerContext(prev => ({ ...prev, index: newIndex }))
    setViewerImageUrl(items[newIndex])
  }

  // Render helpers
  const renderObjectInsuredImages = () => {
    // Render only the available object insured images
    return objectItems.map((url, index) => (
      <ComparePolicyImageItem key={index}>
        <ComparePolicyImageTitle>{objectPositions[index]}</ComparePolicyImageTitle>
        <ImageComponent
          value={url}
          style={{
            width: '100%',
            height: 'auto',
            aspectRatio: '5 / 3',
            objectFit: 'cover',
            maxWidth: '250px'
          }}
          onClickImage={() => handleOpenMedia(url, { type: 'object', index, items: objectItems })}
        />
      </ComparePolicyImageItem>
    ))
  }

  const renderClaimImages = (attributesData) => {
    const items = get(attributesData, 'value', [])
    if (!Array.isArray(items) || items.length === 0) return null

    return items.map((url, index) => (
      <ComparePolicyImageItem key={index}>
        <ComparePolicyImageTitle>File {index + 1}</ComparePolicyImageTitle>
        <ImageComponent
          value={url}
          style={{
            width: '100%',
            height: 'auto',
            aspectRatio: '5 / 3',
            objectFit: 'cover',
            maxWidth: '250px'
          }}
          onClickImage={() => handleOpenMedia(url, { type: 'claim', index, items })}
        />
      </ComparePolicyImageItem>
    ))
  }

  return (
    <Modal
      visible={visible}
      title="Compare With Policy Data"
      onCancel={onClose}
      footer={[
        <Button key="close" onClick={onClose}>
          Close
        </Button>
      ]}
      width={'95%'}
      height={'80vh'}
    >
      <ComparePolicyModalContainer>
        <ComparePolicyModalItem>
            <h2>Object Insured Image</h2>
            <ComparePolicyImageContainer>
                {renderObjectInsuredImages()}
            </ComparePolicyImageContainer>
        </ComparePolicyModalItem>
        <ComparePolicyModalItem>
            <h2>Claim Image</h2>
            <ComparePolicyImageContainer>
                {renderClaimImages(getAttributesByName(formData, filterKey))}
            </ComparePolicyImageContainer>
        </ComparePolicyModalItem>
      </ComparePolicyModalContainer>
      {/* Image viewer and PDF viewer */}
      <Viewer
        visible={viewerVisible}
        imageUrl={viewerImageUrl}
        onClose={() => setViewerVisible(false)}
        items={viewerContext?.items}
        index={viewerContext?.index}
        onPrev={handlePrev}
        onNext={handleNext}
      />
      <PdfViewerModal visible={pdfVisible} onClose={() => setPdfVisible(false)} fileUrl={pdfUrl} />
    </Modal>
  )
}

export default ComparePolicyModal
