import React, { Component } from 'react'
import { connect } from 'react-redux'
import { get } from 'lodash'
import { Button, Card, Spin, Row, Col, Modal, notification, Select } from 'antd'
import { ArrowLeftOutlined, LoadingOutlined } from '@ant-design/icons'
import ClaimListHistory from './components/claimHistoryList'
import PolicyInformation from './components/PolicyInformation'
import { findOwner, DisbursementEventGate, APPROVE_REJECT_PERMISSION, DISBURSEMENT_PERMISSION } from '../Components/constant'
import { useGetInternalUserList, useAssignOwner } from '../../../../../request/query/claim'


import { ClaimDetailStyle } from './index.style'
import {
  ClaimDetailsSection,
  Remarks,
  TransactionDetailSection,
  NotificationsTable,
  ClaimForms
} from '../Components'
import GenericForm from '../../../../../components/GenericForm'
import claimActions from '../../../../redux/claims/actions'
import notifActions from '../../../../redux/notifications/actions'
import loadingActions from '../../../../../redux/loading/actions'
import errorActions from '../../../../../redux/error/actions'
import PermissionChecker from '../../../../../components/PermissionChecker'
import MultiBenefitAutoApprovalEvent from '../Components/multiBenefitAutoApprovalEvent'

const { getClaimDetails, triggerClaimEvent, triggerClaimSalvageEvent, resetUploadData } = claimActions
const { getNotificationsList } = notifActions
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions
const allowShowClaimInformation = ['ppagency-car-protection','ppagency-agency-motor-vehicle']
// NOT list for dynamic claim events: buttons whose event matches any of
// these id/code/other values are hidden. e.g. { code: ['payment_triggered'] }
const hiddenClaimEventMatch = { code: [] }

const OwnerSelector = ({ claimDetails, getClaimDetails, loading: detailLoading }) => {
  const { data: users, isLoading: usersLoading } = useGetInternalUserList()
  const { mutate: assignOwner, isLoading: assigning } = useAssignOwner()

  const selectedOwner = findOwner(users, claimDetails?.owner_id)
  const selectedValue = selectedOwner ? String(selectedOwner.id) : undefined

  const handleAssign = (value) => {
    if (!value) return
    const newOwner = findOwner(users, value)
    assignOwner(
      { body: {
        claim_id: claimDetails?.claim_id,
        new_owner: String(value),
        new_owner_name: newOwner?.name || ''
      } },
      {
        onSuccess: (res) => {
          notification.success({ message: get(res, 'data.message') || 'Owner assigned successfully' })
          getClaimDetails({ query: { claim_id: claimDetails?.claim_id } })
        },
        onError: (err) => {
          notification.error({ message: get(err, 'data.message') || 'Failed to assign owner' })
        }
      }
    )
  }

  return (
    <Card>
      <Row align="middle" gutter={16}>
        <Col><strong>Owner:</strong></Col>
        <Col span={12}>
          <Spin spinning={!!detailLoading || !!usersLoading}>
          <Select
            value={selectedValue}
            onChange={handleAssign}
            showSearch
            allowClear
            optionLabelProp="label"
            filterOption={(input, option) =>
              String(option.label).toLowerCase().includes(input.toLowerCase())
            }
            loading={usersLoading || assigning}
            suffixIcon={usersLoading ? <LoadingOutlined /> : undefined}
            disabled={assigning || detailLoading}
            style={{ width: '100%' }}
          >
            {(users || []).map(user => (
              <Select.Option key={user.id} value={String(user.id)} label={`${user.name || user.email} (${user.email})`}>
                {user.name || user.email} ({user.email})
              </Select.Option>
            ))}
          </Select>
          </Spin>
        </Col>
      </Row>
    </Card>
  )
}

class ClaimDetail extends Component {
  state = {
    showEventModal: false,
    showMultipleFormEventModal: false,
    eventData: {}
  }

  componentDidMount() {
    const { match } = this.props
    const claimID = get(match, 'params.id')
    this.props.getClaimDetails({
      query: {
        claim_id: claimID
      }
    })
    this.props.getNotificationsList({
      query: {
        reference_id: claimID,
        per_page: 5,
        entity_type: 'claim'
      }
    })
    this.props.resetLoadingRedux(['TRIGGER_CLAIM_EVENT', 'TRIGGER_CLAIM_SALVAGE_EVENT', 'GET_CLAIM_DETAIL'])
    this.props.resetErrorRedux(['TRIGGER_CLAIM_EVENT', 'TRIGGER_CLAIM_SALVAGE_EVENT', 'GET_CLAIM_DETAIL'])
  }

  componentWillReceiveProps(nextProps) {
    const { triggerClaimEventLoading, triggerClaimEventError, triggerClaimEventMessage,
      triggerClaimSalvageEventLoading, triggerClaimSalvageEventError, triggerClaimSalvageEventMessage,
      claimDetailsLoading, claimDetailsError, claimDetailsMessage
    } = nextProps

    if (triggerClaimEventLoading === false) {
      if (triggerClaimEventError === false) {
        this.setState({ showEventModal: false,showMultipleFormEventModal: false })
        this.props.resetUploadData()
      }
      notification[triggerClaimEventError ? 'error' : 'success']({ message: triggerClaimEventMessage })
    }
    if (triggerClaimSalvageEventLoading === false) {
      if (triggerClaimSalvageEventError === false) {
        this.setState({ showEventModal: false, showMultipleFormEventModal: false})
        this.props.resetUploadData()
      }
      notification[triggerClaimSalvageEventError ? 'error' : 'success']({ message: triggerClaimSalvageEventMessage })
    }
    if (claimDetailsLoading === false && claimDetailsError) {
      notification['error']({ message: claimDetailsMessage })
      this.props.history.replace({ pathname: '/claim' })
      this.props.resetLoadingRedux(['GET_CLAIM_DETAIL'])
      this.props.resetErrorRedux(['GET_CLAIM_DETAIL'])
    }
  }

  handleBack = () => {
    this.props.history.goBack()
  }

  handleClaimNumberClick = (id) => {
    this.setState({ paramsId: id })
    this.props.history.push(`/claim/${id}`)
    this.props.getClaimDetails({
      query: {
        claim_id: id
      }
    })
    this.props.getNotificationsList({
      query: {
        reference_id: id,
        per_page: 5,
        entity_type: 'claim'
      }
    })
  };

  handleNotificationTableChange = (page) => {
    const { match } = this.props
    const policyID = get(match, 'params.id')
    this.props.getNotificationsList({
      query: {
        reference_id: policyID,
        page,
        per_page: 5,
        entity_type: 'claim'
      }
    })
  }

  handleEventSubmit = (values = {}) => {
    const { claimDetails = {} } = this.props
    const { eventData } = this.state
    const { claim_id: claimID, status } = claimDetails
    if (get(eventData, 'is_salvage')) {
      this.props.triggerClaimSalvageEvent({
        body: {
          data: {
            ...values
          },
          event_code: get(eventData, 'code'),
          salvage_status: get(eventData, 'salvage_status'),
          salvage_slug: get(eventData, 'salvage_slug'),
          claim_id: claimID
        }
      })
    } else {
      this.props.triggerClaimEvent({
        body: {
          data: {
            ...values
          },
          event_code: get(eventData, 'code'),
          status: get(status, 'status_code'),
          claim_id: claimID
        }
      })
    }
  }

  handleMultipleFormEventSubmit = (values = {}) => {

    const { claimDetails = {} } = this.props
    const { eventData } = this.state
    const { claim_id: claimID, status } = claimDetails

    this.props.triggerClaimEvent({
      body: {
        data: {
          multi_benefit_amount_details: {
            ...values,
          }
        },
        event_code: get(eventData, 'code'),
        status: get(status, 'status_code'),
        claim_id: claimID
      }
    })

  }

  renderEvents = () => {
    const { claimDetails = {}, triggerClaimEventLoading, triggerClaimSalvageEventLoading } = this.props
    const { events: claimDetailEvents = [] } = claimDetails

    const events = claimDetailEvents.filter((event) => Array.isArray(event.form_data))

    return events.map(event => (
      <PermissionChecker key={get(event, 'code')} notMatch={hiddenClaimEventMatch} target={event}>
      <Button
        type='primary'
        className={`action-button ${get(event, 'code') === 'claim_rejected' && 'danger-button'}`}
        loading={!!triggerClaimEventLoading || !!triggerClaimSalvageEventLoading}
        onClick={() => {
          if (get(event, 'form_data', []).length > 0) {
            this.setState({ showEventModal: true, eventData: event })
          } else {
            this.setState({ eventData: event }, () => this.handleEventSubmit({}))
          }
        }}
      >
        {get(event, 'code') === "claim_rejected" ? "Claim Rejected by Provider" : get(event, 'display_name')}
      </Button>
      </PermissionChecker>
    ))
  }

  renderMultipleFormEvents = () => {
    const { claimDetails = {}, triggerClaimEventLoading, triggerClaimSalvageEventLoading } = this.props
    const { events: claimDetailEvents = [] } = claimDetails

    const events = claimDetailEvents.filter((event) => !Array.isArray(event.form_data))

    return events.map(event => (
      <PermissionChecker key={get(event, 'code')} notMatch={hiddenClaimEventMatch} target={event}>
      <Button
        type='primary'
        className={`action-button ${get(event, 'code') === 'claim_rejected' && 'danger-button'}`}
        loading={!!triggerClaimEventLoading || !!triggerClaimSalvageEventLoading}
        onClick={() => {
          if (get(event, 'form_data')) {
            this.setState({ showMultipleFormEventModal: true, eventData: event })
          } else {
            this.setState({ eventData: event }, () => this.handleEventSubmit({}))
          }
        }}
      >
        {get(event, 'code') === "claim_rejected" ? "Claim Rejected by Provider" : get(event, 'display_name')}
      </Button>
      </PermissionChecker>
    ))
  }

  render() {
    const { claimDetails = {}, notifDetails = {}, claimDetailsLoading, triggerClaimEventLoading,match } = this.props
    const { remarks, transactions = [], forms } = claimDetails
    const { showEventModal, eventData, showMultipleFormEventModal } = this.state
    const claimID = match.params.id
    return (
      <ClaimDetailStyle>
        <Modal
          visible={showEventModal}
          footer={null}
          closable={false}
        >
          <GenericForm
            formData={get(eventData, 'form_data')}
            title={get(eventData, 'display_name')}
            closeModal={() => {
              this.setState({ showEventModal: false })
              this.props.resetUploadData()
            }}
            handleFinish={this.handleEventSubmit}
            visible={showEventModal}
            loading={triggerClaimEventLoading}
          />
        </Modal>

        <Modal
          visible={showMultipleFormEventModal}
          footer={null}
          closable={false}
        >
          <MultiBenefitAutoApprovalEvent
            formData={get(eventData, 'form_data')}
            title={get(eventData, 'display_name')}
            closeModal={() => {
              this.setState({ showMultipleFormEventModal: false })
              this.props.resetUploadData()
            }}
            submitEvent={this.handleMultipleFormEventSubmit}
            eventData={eventData}
            visible={showMultipleFormEventModal}
            loading={triggerClaimEventLoading}
          />

        </Modal>
        <Spin spinning={!!claimDetailsLoading}>
          <Row justify="space-between">
            <Col>
              <Button
                type='primary'
                icon={<ArrowLeftOutlined />}
                onClick={this.handleBack}
              >
                Back
              </Button>
            </Col>
            <Col className='event-col'>
              <PermissionChecker requiredPermission={[APPROVE_REJECT_PERMISSION, DISBURSEMENT_PERMISSION]}>
                <DisbursementEventGate events={get(claimDetails, 'events', [])}>
                <Row justify='end'>
                  {this.renderEvents()}
                </Row>
                </DisbursementEventGate>
              </PermissionChecker>
              <PermissionChecker requiredPermission={[APPROVE_REJECT_PERMISSION, DISBURSEMENT_PERMISSION]}>
                <DisbursementEventGate events={get(claimDetails, 'events', [])}>
                <Row justify='end'>
                  {this.renderMultipleFormEvents()}
                </Row>
                </DisbursementEventGate>
              </PermissionChecker>
            </Col>
          </Row>
          <Card>
            <ClaimDetailsSection
              claimDetails={claimDetails}
            />
          </Card>
          <OwnerSelector claimDetails={claimDetails} loading={claimDetailsLoading} getClaimDetails={this.props.getClaimDetails} />
          {allowShowClaimInformation.some(i=>i===claimDetails?.display_name) && <>
            <Card>
              <ClaimListHistory claimDetail={claimDetails} handleClaimNumberClick={this.handleClaimNumberClick}/>
            </Card>
            <Card>
              <PolicyInformation claimDetail={claimDetails} loading={claimDetailsLoading} />
            </Card>
          </>}
          <Card>
            <Remarks
              remarks={remarks}
            />
          </Card>
          {
            transactions.length > 0 &&
            <Card>
              <TransactionDetailSection
                transactions={transactions}
              />
            </Card>
          }
          <Card>
            <ClaimForms
              claimForms={forms}
              claimID={claimID}
            />
          </Card>
          <Card>
            <NotificationsTable
              notificationsData={notifDetails}
              handleTableChange={this.handleNotificationTableChange}
            />
          </Card>
        </Spin>
      </ClaimDetailStyle>
    )
  }
}

export default connect(state => ({
  claimDetails: state.Claim.claimDetails,
  notifDetails: state.Notification.notifDetails,

  claimDetailsError: state.Error.GET_CLAIM_DETAIL,
  claimDetailsLoading: state.Loading.GET_CLAIM_DETAIL,
  claimDetailsMessage: state.Claim.claimDetailsMessage,

  triggerClaimEventMessage: state.Claim.triggerClaimEventMessage,
  triggerClaimEventLoading: state.Loading.TRIGGER_CLAIM_EVENT,
  triggerClaimEventError: state.Error.TRIGGER_CLAIM_EVENT,

  triggerClaimSalvageEventMessage: state.Claim.triggerClaimSalvageEventMessage,
  triggerClaimSalvageEventLoading: state.Loading.TRIGGER_CLAIM_SALVAGE_EVENT,
  triggerClaimSalvageEventError: state.Error.TRIGGER_CLAIM_SALVAGE_EVENT,
}), {
  getClaimDetails,
  getNotificationsList,
  triggerClaimEvent,
  triggerClaimSalvageEvent,
  resetUploadData,
  resetLoadingRedux,
  resetErrorRedux
})(ClaimDetail)

export { OwnerSelector }
