import React, { useState } from 'react'
import { ClaimFormStyle } from './component.style'
import Form from './form'
import {
  useGetProvinceList,
  useGetCityList,
  useGetWorkshopList,
} from '../../../../../request/query/bengkel'

const ClaimForms = ({ claimForms = [], claimID }) => {
  const [selectedProvince, setSelectedProvince] = useState(null)
  const [selectedCity, setSelectedCity] = useState(null)

  const { data: provinces = [], isLoading: provincesLoading } = useGetProvinceList()
  const { data: cities = [], isLoading: citiesLoading } = useGetCityList(selectedProvince)
  const { data: workshops = [], isLoading: workshopsLoading } = useGetWorkshopList({
    claimId: claimID,
    provinceId: selectedProvince,
    cityId: selectedCity,
  })

  const bengkelOptions = {
    province: provinces.map(p => [
      JSON.stringify({ id: p.ProvinceId, name: p.ProvinceName }),
      p.ProvinceName,
    ]),
    city: cities.map(c => [
      JSON.stringify({ id: c.CityID, name: c.CityName }),
      c.CityName,
    ]),
    workshop: workshops.map(w => [
      JSON.stringify({ id: w.WorkshopId, name: w.WorkshopName }),
      w.WorkshopName,
    ]),
  }

  const handleBengkelFieldChange = (fieldName, value) => {
    if (fieldName === 'sc_province') {
      setSelectedProvince(value)
      setSelectedCity(null)
    }
    if (fieldName === 'sc_city') {
      setSelectedCity(value)
    }
  }

  const bengkelLoading = {
    province: provincesLoading && !provinces.length,
    city: citiesLoading && !!selectedProvince,
    workshop: workshopsLoading && !!selectedProvince && !!selectedCity,
  }

  return (
    <ClaimFormStyle>
      <Form
        claimForms={claimForms}
        claimID={claimID}
        bengkelOptions={bengkelOptions}
        bengkelLoading={bengkelLoading}
        onBengkelFieldChange={handleBengkelFieldChange}
      />
    </ClaimFormStyle>
  )
}

export default ClaimForms
