import React from 'react'
import { Table, Row, Tag, Button } from 'antd'
import { DownloadOutlined, FilterOutlined, CloseOutlined } from '@ant-design/icons'

import { DataTableStyle } from './component.style'
import { TableColumns, FILTER_DISPLAY_NAME_MAP, resolveOwnerName } from './constant'
import { useGetInternalUserList } from '../../../../../request/query/claim'

const ClaimListTable = ({
  history,
  claimList = {},
  loading,
  tableFilters = {},
  currentUserId,
  ownerFilterDisabled = false,
  page,
  pageSize,
  emailLoading,
  handleSearch,
  handleClearFilter,
  removeFilter,
  handleTableChange,
  handleDownload
}) => {
  const { data, meta_data = {} } = claimList
  const { total_records: totalRecords } = meta_data

  const handleClickDetail = id => {
    history.push({ pathname: `claim/${id}`, search: '' })
  }
  const { data: ownerUsers = [] } = useGetInternalUserList()

  const ownerName = (id) => resolveOwnerName(ownerUsers, id)

  // owner_id arrives as an array when picked from the filter dropdown and as a
  // string when restored from the URL, so resolve the display value before the shape check
  const filterTagValue = (key, value) => {
    const values = Array.isArray(value) ? value : [value]
    return values.map(v => (key === 'owner_id' ? ownerName(v) : v)).join(' - ')
  }

  const tableApi = { handleSearch, handleClickDetail, currentUserId, ownerUsers, ownerFilterDisabled }
  const columns = TableColumns(tableApi)

  return (
    <DataTableStyle>
      <Row justify='space-between' className='button-row'>
        <Button
          type='primary'
          icon={<FilterOutlined />}
          onClick={handleClearFilter}
        >
          Clear Filter
        </Button>
        <Button
          type='primary'
          icon={<DownloadOutlined />}
          onClick={handleDownload}
          loading={!!emailLoading}
        >
          Download
        </Button>
      </Row>
      {
        Object.keys(tableFilters).length > 0 &&
        <Row className='filters-row' align='middle'>
          <div className='filters-header'>Filters Applied:</div>
          <div className='tag-container'>
            {
              Object.keys(tableFilters).map(key =>
                <Tag key={key} color='geekblue' onClick={() => removeFilter(key)} closable closeIcon={<CloseOutlined className='close-icon' onClick={() => removeFilter(key)} />}>
                  {FILTER_DISPLAY_NAME_MAP[key]} : {filterTagValue(key, tableFilters[key])}
                </Tag>
              )
            }
          </div>
        </Row>
      }
      <Table
        dataSource={data}
        columns={columns}
        loading={!!loading}
        rowKey='claim_id'
        onChange={handleTableChange}
        scroll={{
          x: true
        }}
        pagination={{
          total: totalRecords,
          pageSize,
          current: page
        }}
      />
    </DataTableStyle>
  )
}

export default ClaimListTable
