import React, { useState, useRef, useCallback } from 'react'
import { Button, Modal } from 'antd'
import { Document, Page } from 'react-pdf'
import { RollbackOutlined } from '@ant-design/icons'
import FooterBar from './PdfViewerModal.style'

const PdfViewerModal = ({ visible, onClose, fileUrl }) => {
  const [numPages, setNumPages] = useState(null)
  const [pdfRotation, setPdfRotation] = useState(0)
  const downloadRef = useRef(null)

  const onDocumentLoadSuccess = useCallback(({ numPages }) => {
    setNumPages(numPages)
  }, [])

  const handleRotateRightPDF = useCallback(() => {
    setPdfRotation(prev => (prev + 90) % 360)
  }, [])

  const handleRotateLeftPDF = useCallback(() => {
    // add 270 instead of subtracting to avoid negative modulo issues
    setPdfRotation(prev => (prev + 270) % 360)
  }, [])

  const getCurrentPageOrientation = useCallback(() => {
    return pdfRotation === 90 || pdfRotation === 270 ? 'landscape' : 'portrait'
  }, [pdfRotation])

  const handleDownload = useCallback(async () => {
    if (!fileUrl || typeof fileUrl !== 'string') {
      alert('Unable to download the file. Invalid file URL.')
      return
    }

    try {
      const response = await fetch(fileUrl, { method: 'GET' })
      if (!response.ok) throw new Error('Failed to fetch file.')
      const blob = await response.blob()
      const url = URL.createObjectURL(blob)

      if (downloadRef.current) {
        downloadRef.current.href = url
        downloadRef.current.download = fileUrl.split('/').pop()
        downloadRef.current.click()

        URL.revokeObjectURL(url)
      }
    } catch (error) {
      alert('Unable to download the file. Please try again.')
    }
  }, [fileUrl])

  return (
    <Modal
      title="PDF Document"
      visible={visible}
      footer={null}
      onCancel={onClose}
      width={getCurrentPageOrientation() === 'landscape' ? '90%' : '60%'}
      bodyStyle={{ overflow: 'auto', display: 'flex', justifyContent: 'center', paddingBottom: '60px' }}
    >
      <Document file={fileUrl} onLoadSuccess={onDocumentLoadSuccess} className="pdf-document">
        {Array.from(new Array(numPages), (el, index) => (
          <Page key={`page_${index + 1}`} pageNumber={index + 1} className="pdf-page" width={600} rotate={pdfRotation} />
        ))}
      </Document>
      <FooterBar orientation={getCurrentPageOrientation()}>
        <Button type="default" onClick={handleRotateLeftPDF} icon={<RollbackOutlined />} />
        <Button type="default" onClick={handleRotateRightPDF} icon={<RollbackOutlined style={{ transform: 'scaleX(-1)' }} />} />
        <Button key="download" type="primary" onClick={handleDownload}>
          Download
        </Button>
        <a ref={downloadRef} href="/" style={{ display: 'none' }} rel="noopener noreferrer">Download</a>
      </FooterBar>
    </Modal>
  )
}

export default PdfViewerModal
