import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Form, Select, Input, Button, Row, Upload, message, notification, DatePicker, InputNumber } from 'antd'
import { LoadingOutlined, PlusOutlined } from "@ant-design/icons"
import { get } from 'lodash'

import { GenericFormStyle, PDFPreview } from './index.style'
import claimsAction from '../../containers/redux/claims/actions'
import loadingActions from '../../redux/loading/actions'
import errorActions from '../../redux/error/actions'
import { useAppConfig } from '../../request/query/app'

const { generateSignedUrl, resetUploadData } = claimsAction
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

const FormItem = Form.Item
const { Option } = Select
const { TextArea } = Input

const dummyRequest = ({onSuccess }) => {
  setTimeout(() => {
    onSuccess('ok')
  }, 0)
}

function getBase64(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.readAsDataURL(file)
    reader.onload = () => resolve(reader.result)
    reader.onerror = error => reject(error)
  })
}

export function getFileType(file) {

  if (!file) return 'image/png'

  if (file.startsWith('https')) {
    if (file.endsWith('png')) {
      return 'image/png'
    } if (file.endsWith('jpeg')) {
      return 'image/jpeg'
    } if (file.endsWith('jpg')) {
      return 'image/jpg'
    }
    if (file.endsWith('pdf')) {
      return 'application/pdf'
    }
    return 'image/png'
  }

  const indexOfSemiColon = file.indexOf(';')

  if (indexOfSemiColon) {
    return file.slice(5, indexOfSemiColon)
  }

}

class GenericForm extends Component {
  constructor(props) {
    super(props)
    this.state = {
      visibleModal: true,
      showOtherInput: false,
      attributeName: '',
      filePreview: {},
      fileName: {},
      makeFileUrlPublic: []
    }
    this.formRef = React.createRef()
  }

  componentDidMount() {
    this.props.resetLoadingRedux(['GENERATE_SIGNED_URL'])
    this.props.resetErrorRedux(['GENERATE_SIGNED_URL'])
  }

  componentWillUnmount() {
    this.setState({
      visibleModal: true,
      showOtherInput: false,
      attributeName: '',
      filePreview: {},
      fileName: {},
      makeFileUrlPublic: []
    })
  }

  componentWillReceiveProps(nextProps) {
    const {
      visible,
      signedUrl,
      triggerClaimSalvageEventError,
      triggerClaimSalvageEventLoading,
      triggerClaimEventError,
      triggerClaimEventLoading,
      generateSignedUrlLoading,
      generateSignedUrlError,
      generateSignedUrlStatus
    } = nextProps
    const { attributeName, makeFileUrlPublic } = this.state

    if (visible !== this.state.visibleModal) {
      this.setState({ visibleModal: visible })
      if (!visible) {
        this.formRef.current.resetFields()
        this.setState({
          showOtherInput: false,
        })
        this.props.closeModal()
      }
    }

    if (triggerClaimEventLoading === false) {
      if (triggerClaimEventError === false) {
        this.setState({
          visibleModal: true,
          showOtherInput: false,
          attributeName: '',
          filePreview: {},
          fileName: {},
          makeFileUrlPublic: []
        })
      }
      this.props.resetLoadingRedux(['TRIGGER_CLAIM_EVENT'])
      this.props.resetErrorRedux(['TRIGGER_CLAIM_EVENT'])
    }
    if (triggerClaimSalvageEventLoading === false) {
      if (triggerClaimSalvageEventError === false) {
        this.setState({
          visibleModal: true,
          showOtherInput: false,
          attributeName: '',
          filePreview: {},
          fileName: {},
          makeFileUrlPublic: []
        })
      }
      this.props.resetLoadingRedux(['TRIGGER_CLAIM_SALVAGE_EVENT'])
      this.props.resetErrorRedux(['TRIGGER_CLAIM_SALVAGE_EVENT'])
    }

    if (generateSignedUrlLoading === false) {
      if (generateSignedUrlError) {
        notification['error']({ message: generateSignedUrlStatus })
      }
      if (!Array.isArray(signedUrl) && Object.keys(signedUrl).length) {
        const url = get(signedUrl, 'url')
        const newMakeFileUrlPublic = [...makeFileUrlPublic, signedUrl]
        this.setState({
          makeFileUrlPublic: newMakeFileUrlPublic
        })
        this.formRef.current.setFieldsValue({
          ...this.formRef.current.getFieldsValue(),
          [attributeName]: url
        })
      }
      this.props.resetLoadingRedux(['GENERATE_SIGNED_URL'])
      this.props.resetErrorRedux(['GENERATE_SIGNED_URL'])
    }
  }

  handleFinish = (values) => {
    const { userSlab } = this.props
    const { max_amount: maxAmount = 0, min_amount: minAmount = 0 } = userSlab

    values['makeFileUrlPublic'] = this.state.makeFileUrlPublic

    if (get(values, 'amount')) {
      let amount = get(values, 'amount')
      values['amount'] = parseInt(amount).toString()
      if (amount < minAmount || amount > maxAmount) {
        return notification['error']({ message: `You dont have permission to disburse amount greater than ${maxAmount}` })
      }
    }
    // console.log("on submit", values)
    this.props.handleFinish(values)
  }

  uploadImage = async (info, name) => {
    const acceptedFileType = ['image/jpeg', 'image/jpg', 'image/png', 'application/pdf']
    if (info.file.status === 'done' || info.file.status === 'error') {
      const isLt10KB = info.file.size / 1024 / 1024 < 0.01
      const isGt10MB = info.file.size / 1024 / 1024 > 10
      if (isLt10KB) {
        message.error('Photo terlalu kecil, min 10kb')
        return
      }
      if (isGt10MB) {
        message.error('Photo terlalu besar, max 10mb')
        return
      }
      if ((acceptedFileType.includes(info.file.type) && !isLt10KB && !isGt10MB)) {
        try {
          const { file } = info
          const formData = {}
          formData['name'] = file.name
          formData['type'] = file.type
          const filePreview = await getBase64(file.originFileObj)
          const uploadedFile = file.originFileObj
          const stateFilePreview = this.state.filePreview
          const stateFileName = this.state.fileName
          this.setState({
            uploadLoader: true,
            filePreview: {
              ...stateFilePreview,
              [name]: filePreview
            },
            fileName: {
              ...stateFileName,
              [name]: file.name
            },
            attributeName: name
          })
          this.props.generateSignedUrl({
            body: {
              formData
            },
            uploadedFile
          })
        } catch (error) {
          message.error('Ada yang bermasalah, reload dan ulangi kembali')
        }
      } else {
        notification['error']({ message: 'Check your file type' })
      }
    }
  }

  handleOnChangeSelect = (value, name) => {
    this.setState({ showOtherInput: value === 'other' })
    if (value !== 'other') {
      this.formRef.current.setFieldsValue({ [name]: value })
    } else {
      this.formRef.current.setFieldsValue({ [name]: undefined })
    }
  }

  renderFilePreview = (filePreview, fileName) => {
    const type = getFileType(filePreview)

    const isImage = ['image/jpeg', 'image/jpg', 'image/png'].includes(type)

    if (isImage) {
      return (
        <img
          src={filePreview}
          width="90%"
          alt="claim_document"
        />
      )
    }

    const isPdf = ['application/pdf'].includes(type)

    if (isPdf) {
      return <PDFPreview >
        <div>
          <a
            download={fileName}
            onClick={(event) => { event.stopPropagation() }}
            href={filePreview}>
            {fileName}
          </a>
        </div>
      </PDFPreview>
    }

    return null
  }

  renderAttribute = (type, label, name, options, value) => {
    const { generateSignedUrlLoading, title } = this.props
    const { showOtherInput, filePreview, fileName } = this.state
    const uploadButton = (
      <div>
        {generateSignedUrlLoading ? <LoadingOutlined /> : <PlusOutlined />}
        <div className='upload-button'>Upload</div>
      </div>
    )
    switch (type) {
      case 'choices':
        return (
          <div>
            <Select
              showSearch
              key={label}
              placeholder={`Select ${label}`}
              optionFilterProp="children"
              value={options?.length === 1 || title === 'Accept' ? options[0][0] : undefined}
              allowClear
              dropdownMatchSelectWidth={false}
              onChange={value => this.handleOnChangeSelect(value, name)}
              filterOption={(input, option) =>
                option.label.toLowerCase().indexOf(input.toLowerCase()) >= 0
              }
              disabled={options?.length === 1 || title === 'Accept'}
            >
              {options.map((option) => (
                <Option key={option[0]} value={option[0]}>
                  {option[1]}
                </Option>
              ))}
            </Select>
            {showOtherInput && name === 'remarks' && <FormItem name="remarks" rules={[{ required: true, message: 'Please input your remarks!' }]}><TextArea className="other-textArea" /></FormItem>}
          </div>
        )
      case "image":
        return <Upload
          name="avatar"
          listType="picture-card"
          onChange={(info) => this.uploadImage(info, name)}
          customRequest={dummyRequest}
          disabled={!!generateSignedUrlLoading}
          accept='.jpg, .jpeg, .png, .pdf'
          showUploadList={false}
        >
          {
            filePreview[name]
              ?
              this.renderFilePreview(filePreview[name], fileName[name])
              :
              uploadButton
          }
        </Upload>
      case 'int':
        return (
          <InputNumber
            placeholder={`Enter ${label}`}
            formatter={value => `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ',')}
            parser={value => value.replace(/\$\s?|(,*)/g, '')}
            className='input-number'
          />
        )
      case 'date':
        return <DatePicker />
      case 'datetime':
        return <DatePicker />
      case 'string':
      case 'text':
        if (name === 'amount') {
          return <InputNumber
            placeholder={`Enter ${label}`}
            disabled={!!value}
            formatter={value => `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ',')}
            parser={value => value.replace(/\$\s?|(,*)/g, '')}
            className='input-number'
          />
        } else {
          return <Input
            placeholder={`Enter ${label}`}
          />
        }
      default:
        return <Input
          key={label}
          placeholder={`Enter ${label}`}
        />
    }
  }

  closeModal = () => {
    this.setState({ filePreview: {}, fileName: {}, makeFileUrlPublic: [], attributeName: '' }, () => {
      this.formRef.current.resetFields()
      this.props.resetUploadData()
      this.props.closeModal()
    })
  }

  render() {
    const { formData = [], title, generateSignedUrlLoading, loading } = this.props

    return (
      <GenericFormStyle>
        <div className='modal-header'>
          {title}
        </div>
        <div className='form-body'>
          <Form ref={this.formRef} onFinish={this.handleFinish}>
            {
              formData.map(({ name, type, options, label, required, value }) =>
              {
                // console.log("value generic form", value)
                return (<FormItem name={name} label={label} key={name}
                  rules={[{ required: required, message: `Please input your ${label}!` }]}
                  initialValue={type === 'choices' && (options?.length === 1 || title === 'Accept') ? options[0][0] : value
                  }
                  help={type === 'time' && "Time should be in the format of HH:mm:ss"}
                >
                  {this.renderAttribute(type, label, name, options, value,title)}
                </FormItem>)
              }
              )
            }
            <Row justify='end'>
              <Button
                className='cancel-button'
                onClick={this.closeModal}
              >
                Cancel
              </Button>
              <FormItem>
                <Button
                  htmlType='submit'
                  loading={!!loading}
                  type='primary'
                  className='submit-button'
                  disabled={!!generateSignedUrlLoading}
                >
                  Submit
                </Button>
              </FormItem>
            </Row>
          </Form>
        </div>
      </GenericFormStyle>
    )
  }
}

export default function WrappedGenericForm(props) {
  const { slab } = useAppConfig()
  return <GenericFormWrapped userSlab={slab} {...props} />
}

const GenericFormWrapped = connect(state => ({
  generateSignedUrlLoading: state.Loading.GENERATE_SIGNED_URL,
  generateSignedUrlError: state.Error.GENERATE_SIGNED_URL,
  generateSignedUrlStatus: state.Claim.signedUrlStatus,
  signedUrl: state.Claim.signedUrl,
  triggerClaimEventMessage: state.Claim.triggerClaimEventMessage,
  triggerClaimEventLoading: state.Loading.TRIGGER_CLAIM_EVENT,
  triggerClaimEventError: state.Error.TRIGGER_CLAIM_EVENT,
  triggerClaimSalvageEventMessage: state.Claim.triggerClaimSalvageEventMessage,
  triggerClaimSalvageEventLoading: state.Loading.TRIGGER_CLAIM_SALVAGE_EVENT,
  triggerClaimSalvageEventError: state.Error.TRIGGER_CLAIM_SALVAGE_EVENT,
}), {
  resetLoadingRedux,
  resetErrorRedux,
  generateSignedUrl,
  resetUploadData
})(GenericForm)
