import ConfigChecker from '../../../../../components/ConfigChecker'
import { useAppConfig } from '../../../../../request/query/app'

export const APPROVE_REJECT_PERMISSION = 'can_approve_reject_claim'
export const DISBURSEMENT_PERMISSION = 'can_trigger_disbursement'
export const ACCEPTED_EVENT_CODE = 'claim_accepted'

const hasCodename = (userPermissions = [], codename) =>
  (userPermissions || []).some((entry) => (entry || {}).codename === codename)

// Disbursement-only viewers can act on claim events, except once the
// backend offers claim_accepted the event buttons must disappear.
// Users holding the approve permission always keep the buttons.
export const shouldHideDisbursementEvents = (events = [], userPermissions = []) => {
  const isDisbursementOnly =
    hasCodename(userPermissions, DISBURSEMENT_PERMISSION) &&
    !hasCodename(userPermissions, APPROVE_REJECT_PERMISSION)
  if (!isDisbursementOnly) return false
  return (events || []).some((event) => (event || {}).code === ACCEPTED_EVENT_CODE)
}

export const DisbursementEventGate = ({ events, children }) => {
  const { userPermissions } = useAppConfig()
  if (shouldHideDisbursementEvents(events, userPermissions)) return null
  return children || null
}


const CheckPermission = ({children}) => {
  return (
    <PermissionChecker requiredPermission={"view_claim_details"}>
      <ConfigChecker
        requiredConfig={"DISPLAY_CLAIM_DETAILS"}
        requiredValue="1"
      >
        {children}
      </ConfigChecker>
    </PermissionChecker>)
}

export const findOwner = (users, ownerId) =>
  (users || []).find(u => String(u.id) === String(ownerId))

export const resolveOwnerName = (users, ownerId) => {
  if (!ownerId) return '-'
  const owner = findOwner(users, ownerId)
  return owner ? (owner.name || owner.email) : ownerId
}

